window.__OPENSTAX_PHYSICS__[23] = {"schemaVersion":"4.0.0-physics","generatedAt":"2026-11-27T01:33:30.921Z","number":23,"code":"ch23","slug":"particle-physics","title":"Particle Physics","titleVi":"Vật Lý Hạt Cơ Bản & Mô Hình Chuẩn (Particle Physics)","sections":[{"uid":"hsphys.ch23.sec00","moduleId":"m54584","number":"23.0","slug":"introduction","title":"Introduction","isIntroduction":true,"learningObjectives":[],"bilingualGuide":null,"keyEquations":[],"subsections":[{"uid":"hsphys.ch23.sec00.sub01","title":"Chapter Introduction","summaryVi":null,"paragraphs":["Following ideas remarkably similar to those of the ancient Greeks, we continue to look for smaller and smaller structures in nature, hoping ultimately to find and understand the most fundamental building blocks that exist. Atomic physics deals with the smallest units of elements and compounds. In its study, we have found a relatively small number of atoms with systematic properties, and these properties have explained a tremendous range of phenomena. Nuclear physics is concerned with the nuclei of atoms and their substructures. Here, a smaller number of components—the proton and neutron—make up all nuclei. Exploring the systematic behavior of their interactions has revealed even more about matter, forces, and energy. Particle physics deals with the substructures of atoms and nuclei and is particularly aimed at finding those truly fundamental particles that have no further substructure. Just as in atomic and nuclear physics, we have found a complex array of particles and properties with systematic characteristics analogous to the periodic table and the chart of nuclides. An underlying structure is apparent, and there is some reason to think that we are finding particles that have no substructure. Of course, we have been in similar situations before. For example, atoms were once thought to be the ultimate substructures. It is possible that we could continue to find deeper and deeper structures without ever discovering the ultimate substructure—in science there is never complete certainty. See [Figure 23.0].","The properties of matter are based on substructures called molecules and atoms. Each atom has the substructure of a nucleus surrounded by electrons, and their interactions explain atomic properties. Protons and neutrons—and the interactions between them—explain the stability and abundance of elements and form the substructure of nuclei. Protons and neutrons are not fundamental—they are composed of quarks. Like electrons and a few other particles, quarks may be the fundamental building blocks of all matter, lacking any further substructure. But the story is not complete because quarks and electrons may have substructures smaller than details that are presently observable.","This chapter covers the basics of particle physics as we know it today. An amazing convergence of topics is evolving in particle physics. We find that some particles are intimately related to forces and that nature on the smallest scale may have its greatest influence on the large scale character of the universe. It is an adventure exceeding the best science fiction because it is not only fantastic but also real."],"figures":[{"sourceId":"fs-id1167063749178","filename":"CNX_HSPhysics_23_00_LHC.jpg","relativePath":"media/CNX_HSPhysics_23_00_LHC.jpg","alt":"The photograph shows a series of tubes and structural elements that make up the Large Hadron Collider. The five staircases on the sides of the collider show the very large size of the experimental device."},{"sourceId":"fs-id1167067092298","filename":"CNX_HSPhysics_23_00_Structure.jpg","relativePath":"media/CNX_HSPhysics_23_00_Structure.jpg","alt":"A sequence of six images is shown: a solid, a molecule, an atom, a nucleus, a nucleon (a particle that makes up the nucleus—either a proton or a neutron), and a quark. Each image in the sequence is connected to the next one by an arrow from the prior image, showing that the ones on the right are smaller and smaller constructs of each preceding one on the left. In other words, the solid is made of molecules, the molecule is made of atoms, and so on."}],"tables":[]}],"workedExamples":[],"snapLabs":[],"tipsAndFeatures":[],"summaryPoints":[],"glossary":[],"assessments":[],"stats":{"learningObjectiveCount":0,"keyEquationCount":0,"subsectionCount":1,"workedExampleCount":0,"snapLabCount":0,"glossaryCount":0,"assessmentCount":0}},{"uid":"hsphys.ch23.sec01","moduleId":"m54593","number":"23.1","slug":"the-four-fundamental-forces","title":"The Four Fundamental Forces","isIntroduction":false,"learningObjectives":["Define, describe, and differentiate the four fundamental forces","Describe the carrier particles and explain how their exchange transmits force","Explain how particle accelerators work to gather evidence about particle physics"],"bilingualGuide":{"notebookSummaryVi":"4 Lực cơ bản trong tự nhiên (Mạnh > Điện từ > Yếu > Hấp dẫn), các hạt truyền tương tác (Gluon, Photon, W±/Z⁰, Graviton), Giản đồ Feynman và Máy gia tốc hạt.","wordProblemCues":[{"phraseEn":"four fundamental forces","meaningVi":"Mạnh, Điện từ, Yếu, Hấp dẫn","mathNotation":"Strong > EM > Weak > Gravity"}],"commonTrapsVi":["Ở thang hạt nhân, lực Hấp dẫn yếu nhất (yếu hơn lực Mạnh tới ~10³⁸ lần!), nhưng ở thang vũ trụ nó thống trị vì luôn hút và tầm tác dụng vô hạn!"]},"keyEquations":[],"subsections":[{"uid":"hsphys.ch23.sec01.sub01","title":"Understanding the Four Forces","summaryVi":null,"paragraphs":["The gravitational force is most familiar to us because it describes so many of our common observations. It explains why a dropped ball falls to the ground and why our planet orbits the Sun. It gives us the property of weight and determines much about the motion of objects in our daily lives. Because gravitational force acts between all objects of mass and has the ability to act over large distances, the gravitational force can be used to explain much of what we observe and can even describe the motion of objects on astronomical scales! That said, gravity is incredibly weak compared to the other fundamental forces and is the weakest of all of the fundamental forces. Consider this: The entire mass of Earth is needed to hold an iron nail to the ground. Yet with a simple magnet, the force of gravity can be overcome, allowing the nail to accelerate upward through space.","The electromagnetic force is responsible for both electrostatic interactions and the magnetic force seen between bar magnets. When focusing on the electrostatic relationship between two charged particles, the electromagnetic force is known as the coulomb force . The electromagnetic force is an important force in the chemical and biological sciences, as it is responsible for molecular connections like ionic bonding and hydrogen bonding. Additionally, the electromagnetic force is behind the common physics forces of friction and the normal force. Like the gravitational force, the electromagnetic force is an inverse square law. However, the electromagnetic force does not exist between any two objects of mass, only those that are charged.","When considering the structure of an atom, the electromagnetic force is somewhat apparent. After all, the electrons are held in place by an attractive force from the nucleus. But what causes the nucleus to remain intact? After all, if all protons are positive, it makes sense that the coulomb force between the protons would repel the nucleus apart immediately. Scientists theorized that another force must exist within the nucleus to keep it together. They further theorized that this nuclear force must be significantly stronger than gravity, which has been observed and measured for centuries, and also stronger than the electromagnetic force, which would cause the protons to want to accelerate away from each other.","The strong nuclear force is an attractive force that exists between all nucleons . This force, which acts equally between proton-proton connections, proton-neutron connections, and neutron-neutron connections, is the strongest of all forces at short ranges. However, at a distance of 10 13 cm, or the diameter of a single proton, the force dissipates to zero. If the nucleus is large (it has many nucleons), then the distance between each nucleon could be much larger than the diameter of a single proton.","The weak nuclear force is responsible for beta decay, as seen in the equation \\({}_{Z}^{A}{X}_{N} \\to {}_{Z + 1}^{A}{Y}_{N–1} + e + v.\\) Recall that beta decay is when a beta particle is ejected from an atom. In order to accelerate away from the nucleus, the particle must be acted on by a force. Enrico Fermi was the first to envision this type of force. While this force is appropriately labeled, it remains stronger than the gravitational force. However, its range is even smaller than that of the strong force, as can be seen in [Table_23_01]. The weak nuclear force is more important than it may appear at this time, as will be addressed when we discuss quarks."],"figures":[],"tables":[{"sourceId":"Table_23_01","headers":["Force","Approximate Relative Strength [1]","Range"],"rows":[["Gravity","\\({10}^{-38}\\)","\\(∞\\)"],["Weak","\\({10}^{-13}\\)","\\(\\lt {10}^{-18}\\text{m}\\)"],["Electromagnetic","\\({10}^{-2}\\)","\\(∞\\)"],["Strong","1","\\(\\lt {10}^{-15}\\text{m}\\)"]]}]},{"uid":"hsphys.ch23.sec01.sub02","title":"Transmitting the Four Fundamental Forces","summaryVi":null,"paragraphs":["Just as it troubled Einstein prior to formulating the gravitational field theory, the concept of forces acting over a distance had greatly troubled particle physicists. That is, how does one proton know that another exists? Furthermore, what causes one proton to make a second proton repel? Or, for that matter, what is it about a proton that causes a neutron to attract? These mysterious interactions were first considered by Hideki Yukawa in 1935 and laid the foundation for much of what we now understand about particle physics.","Hideki Yukawa’s focus was on the strong nuclear force and, in particular, its incredibly short range. His idea was a blend of particles, relativity, and quantum mechanics that was applicable to all four forces. Yukawa proposed that the nuclear force is actually transmitted by the exchange of particles, called carrier particles , and that what we commonly refer to as the force’s field consists of these carrier particles. Specifically for the strong nuclear force, Yukawa proposed that a previously unknown particle, called a pion , is exchanged between nucleons, transmitting the force between them. [Figure 23.1] illustrates how a pion would carry a force between a proton and a neutron.","In Yukawa’s strong force, the carrier particle is assumed to be transmitted at the speed of light and is continually transferred between the two nucleons shown. The particle that Yukawa predicted was finally discovered within cosmic rays in 1947. Its name, the pion, stands for pi meson, where meson means medium mass ; it’s a medium mass because it is smaller than a nucleon but larger than an electron. Yukawa launched the field that is now called quantum chromodynamics , and the carrier particles are now called gluons due to their strong binding power. The reason for the change in the particle name will be explained when quarks are discussed later in this section.","As you may assume, the strong force is not the only force with a carrier particle. Nuclear decay from the weak force also requires a particle transfer. In the weak force are the following three: the weak negative carrier, W – ; the weak positive carrier, W + ; and the zero charge carrier, Z 0 . As we will see, Fermi inferred that these particles must carry mass, as the total mass of the products of nuclear decay is slightly larger than the total mass of all reactants after nuclear decay.","The carrier particle for the electromagnetic force is, not surprisingly, the photon . After all, just as a lightbulb can emit photons from a charged tungsten filament, the photon can be used to transfer information from one electrically charged particle to another. Finally, the graviton is the proposed carrier particle for gravity. While it has not yet been found, scientists are currently looking for evidence of its existence (see Boundless Physics: Searching for the Graviton ).","So how does a carrier particle transmit a fundamental force? [Figure 23.1] shows a virtual photon transmitted from one positively charged particle to another. The transmitted photon is referred to as a virtual particle because it cannot be directly observed while transmitting the force. [Figure 23.1] shows a way of graphing the exchange of a virtual photon between the two positively charged particles. This graph of time versus position is called a Feynman diagram , after the brilliant American physicist Richard Feynman (1918–1988), who developed it.","The Feynman diagram should be read from the bottom up to show the movement of particles over time. In it, you can see that the left proton is propelled leftward from the photon emission, while the right proton feels an impulse to the right when the photon is received. In addition to the Feynman diagram, Richard Feynman was one of the theorists who developed the field of quantum electrodynamics (QED), which further describes electromagnetic interactions on the submicroscopic scale. For this work, he shared the 1965 Nobel Prize with Julian Schwinger and S.I. Tomonaga. A Feynman diagram explaining the strong force interaction hypothesized by Yukawa can be seen in [Figure 23.1]. Here, you can see the change in particle type due to the exchange of the pi meson.","The relative masses of the listed carrier particles describe something valuable about the four fundamental forces, as can be seen in [Table_23_02]. W bosons (consisting of \\({\\text{W}}^{-}\\) and \\({\\text{W}}^{+}\\) bosons) and Z bosons ( \\({\\text{Z}}^{0}\\) bosons), carriers of the weak nuclear force, are nearly 1,000 times more massive than pions, carriers of the strong nuclear force. Simultaneously, the distance that the weak nuclear force can be transmitted is approximately \\(\\frac{1}{1,000}\\) times the strong force transmission distance. Unlike carrier particles, which have a limited range, the photon is a massless particle that has no limit to the transmission distance of the electromagnetic force. This relationship leads scientists to understand that the yet-unfound graviton is likely massless as well.","From Newton’s Universal Law of Gravitation to Einstein’s field equations, gravitation has held the focus of scientists for centuries. Given the discovery of carrier particles during the twentieth century, the importance of understanding gravitation has yet again gained the interest of prominent physicists everywhere.","With carrier particles discovered for three of the four fundamental forces, it is sensible to scientists that a similar particle, titled the graviton , must exist for the gravitational force. While evidence of this particle is yet to be uncovered, scientists are working diligently to discover its existence.","So what do scientists think about the unfound particle? For starters, the graviton (like the photon) should be a massless particle traveling at the speed of light. This is assumed because, like the electromagnetic force, gravity is an inverse square law, \\(F \\approx \\frac{1}{{r}^{2}}\\) . Scientists also theorize that the graviton is an electrically neutral particle, as an empty space within the influence of gravity is chargeless.","However, because gravity is such a weak force, searching for the graviton has resulted in some unique methods. LIGO, the Laser Interferometer Gravitational-Wave Observatory , is one tool currently being utilized (see [Figure 23.1]). While searching for a gravitational wave to find a carrier particle may seem counterintuitive, it is similar to the approach taken by Planck and Einstein to learn more about the photon. According to wave-particle duality, if a gravitational wave can be found, the graviton should be present along with it. Predicted by Einstein’s theory of general relativity, scientists have been monitoring binary star systems for evidence of these gravitational waves.","Particle accelerators like the Large Hadron Collider (LHC) are being used to search for the graviton through high-energy collisions. While scientists at the LHC speculate that the particle may not exist long enough to be seen, evidence of its prior existence, like footprints in the sand, can be found through gaps in projected energy and momentum.","Some scientists are even searching the remnants of the Big Bang in an attempt to find the graviton. By observing the cosmic background radiation, they are looking for anomalies in gravitational waves that would provide information about the gravity particles that existed at the start of our universe.","Regardless of the method used, scientists should know the graviton once they find it. A massless, chargeless particle with a spin of 2 and traveling at the speed of light—there is no other particle like it. Should it be found, its discovery would surely be considered by future generations to be on par with those of Newton and Einstein."],"figures":[{"sourceId":"fs-id1167063522469","filename":"CNX_HSPhysics_23_01_Pion.jpg","relativePath":"media/CNX_HSPhysics_23_01_Pion.jpg","alt":"This figure shows a sequence of four images in four rows. In the first row, a proton and a neutron are pictured. The proton is on the left and the neutron is on the right. In the second row, a pion leaves the proton and travels toward the neutron, as represented by an arrow. As a result, the proton is now a neutron. In the third row, the pion is still traveling toward the neutron on the right. This image consists of the pion and two neutrons. In the fourth row, a proton is on the right with a neutron on the left. This shows that the pion has been absorbed by the right-side neutron, which has turned into a proton as a result."},{"sourceId":"fs-idm806264480","filename":"CNX_HSPhysics_23_01_Photon.jpg","relativePath":"media/CNX_HSPhysics_23_01_Photon.jpg","alt":"There are two sequences of images in two columns labeled (a) and (b). In part (a), the sequence begins with a photon leaving a proton on the left and moving toward another proton on the right. When it leaves, it propels the left-side proton leftward. Later in the sequence, the photon is received by the proton on the right. Upon receiving the photon, the right-side proton is propelled to the right. Thus the sequence begins with two stationary protons and finishes with two protons traveling in opposite directions. In part (b), the sequence of images shows that the photon cannot be observed. An eye is drawn between two protons. When the photon leaves the left-side proton, it is intercepted by the eye and does not reach the right-side proton. Because this cannot occur, this sequence is evidence of the photon’s virtual nature."},{"sourceId":"fs-id1167063628885","filename":"CNX_HSPhysics_23_01_Feynman.jpg","relativePath":"media/CNX_HSPhysics_23_01_Feynman.jpg","alt":"The diagram shows two positively charged particles traveling upward toward each other. As one positively charged particle (on the left) expels a virtual photon to the right, the charge is projected upward and to the left. The virtual photon is received by the positively charged particle on the right. As a result, this positively charged particle is projected upward and to the right."},{"sourceId":"fs-id1167063625495","filename":"CNX_HSPhysics_23_01_FeynYuk.jpg","relativePath":"media/CNX_HSPhysics_23_01_FeynYuk.jpg","alt":"The diagram shows a proton and a neutron traveling upward toward each other. As the proton expels a virtual pion to the right, it is projected upward and to the left. As a result of expelling this pion, the particle traveling upward and to the left is now a neutron. The virtual pion is received by the neutron on the right. As a result, this particle is projected upward and to the right and is now a proton."},{"sourceId":"fs-id1167063786353","filename":"CNX_HSPhysics_23_01_LIGO_img.jpg","relativePath":"media/CNX_HSPhysics_23_01_LIGO_img.jpg","alt":"The image shows the LIGO Hanford control room. There are desktop computers and large screens showing a variety of graphs, likely showing spectra collected from stars."}],"tables":[{"sourceId":"Table_23_02","headers":["Force","Carrier Particle","Range","Relative Strength [1]"],"rows":[["Gravity","Graviton (theorized)","\\(∞\\)","\\({10}^{-38}\\)"],["Weak","W and Z bosons","\\(\\lt {10}^{-18}\\text{m}\\)","\\({10}^{-2}\\)"],["Electromagnetic","Photon","\\(∞\\)","\\({10}^{-13}\\)"],["Strong","Pi mesons or pions (now known as gluons)","\\(\\lt {10}^{-15}\\text{m}\\)","1"]]}]},{"uid":"hsphys.ch23.sec01.sub03","title":"Accelerators Create Matter From Energy","summaryVi":null,"paragraphs":["Before looking at all the particles that make up our universe, let us first examine some of the machines that create them. The fundamental process in creating unknown particles is to accelerate known particles, such as protons or electrons, and direct a beam of them toward a target. Collisions with target nuclei provide a wealth of information, such as information obtained by Rutherford in the gold foil experiment. If the energy of the incoming particles is large enough, new matter can even be created in the collision. The more energy input or Δ E , the more matter m can be created, according to mass energy equivalence \\(m = \\Delta E/{c}^{2}\\) . Limitations are placed on what can occur by known conservation laws, such as conservation of mass-energy, momentum, and charge. Even more interesting are the unknown limitations provided by nature. While some expected reactions do occur, others do not, and still other unexpected reactions may appear. New laws are revealed, and the vast majority of what we know about particle physics has come from accelerator laboratories. It is the particle physicist’s favorite indoor sport.","Our earliest model of a particle accelerator comes from the Van de Graaff generator . The relatively simple device, which you have likely seen in physics demonstrations, can be manipulated to produce potentials as great as 50 million volts. While these machines do not have energies large enough to produce new particles, analysis of their accelerated ions was instrumental in exploring several aspects of the nucleus.","Another equally famous early accelerator is the cyclotron , invented in 1930 by the American physicist, E.O. Lawrence (1901–1958). [Figure 23.1] is a visual representation with more detail. Cyclotrons use fixed-frequency alternating electric fields to accelerate particles. The particles spiral outward in a magnetic field, making increasingly larger radius orbits during acceleration. This clever arrangement allows the successive addition of electric potential energy with each loop. As a result, greater particle energies are possible than in a Van de Graaff generator.","A synchrotron is a modification of the cyclotron in which particles continually travel in a fixed-radius orbit, increasing speed each time. Accelerating voltages are synchronized with the particles to accelerate them, hence the name. Additionally, magnetic field strength is increased to keep the orbital radius constant as energy increases. A ring of magnets and accelerating tubes, as shown in [Figure 23.1], are the major components of synchrotrons. High-energy particles require strong magnetic fields to steer them, so superconducting magnets are commonly employed. Still limited by achievable magnetic field strengths, synchrotrons need to be very large at very high energies since the radius of a high-energy particle’s orbit is very large.","To further probe the nucleus, physicists need accelerators of greater energy and detectors of shorter wavelength. To do so requires not only greater funding but greater ingenuity as well. Colliding beams used at both the Fermi National Accelerator Laboratory (Fermilab; see [Figure 23.1]) near Chicago and the LHC in Switzerland are designed to reduce energy loss in particle collisions. Typical stationary particle detectors lose a large amount of energy to the recoiling target struck by the accelerating particle. By providing head-on collisions between particles moving in opposite directions, colliding beams make it possible to create particles with momenta and kinetic energies near zero. This allows for particles of greater energy and mass to be created. [Figure 23.1] is a schematic representation of this effect. In addition to circular accelerators, linear accelerators can be used to reduce energy radiation losses. The Stanford Linear Accelerator Center (now called the SLAC National Accelerator Laboratory) in California is home to the largest such accelerator in the world."],"figures":[{"sourceId":"fs-id1167067239829","filename":"CNX_HSPhysics_23_01_Cyclotron.jpg","relativePath":"media/CNX_HSPhysics_23_01_Cyclotron.jpg","alt":"There are two images. On the left is an image of a Van de Graaff generator. On the right is a drawing of a cyclotron. This is created by two semi-circles separated by a gap. In this gap are arrows representing the direction of an alternating electric field. Within the two semi-circles are x symbols showing that the magnetic field is projected upward through the semi-circles. A particle is shown spiraling in an expanding circular pattern from the center of the semi-circles and outward."},{"sourceId":"fs-id1167063582862","filename":"CNX_HSPhysics_23_01_Synchro.jpg","relativePath":"media/CNX_HSPhysics_23_01_Synchro.jpg","alt":"There are three images. The image on the left is a series of magnets connected in a circle by a line. This line shows the direction of an accelerating circulating particle. The next two images are close-ups of a particle traveling from one magnet to the next. In the center image the particle (a proton) is traveling from one tube to the next because an electric field is pushing it in that direction. The electric field is shown by an arrow pointing from a positive charge over the tube the proton is leaving and negative charge over the tube the proton is entering. In the right picture, the proton is leaving the tube it had just entered and is about to enter the next tube in its path. It can be seen that the electric field has switched directions, as the charge over the tube it had previously entered is now positive and the tube it is about to enter is now negative."},{"sourceId":"fs-id1167066856057","filename":"CNX_HSPhysics_23_01_FermiLab.jpg","relativePath":"media/CNX_HSPhysics_23_01_FermiLab.jpg","alt":"The image shows a long circulating tube, shaped like a pair of parallel rings, one pair of rings being much smaller than the other. One end of the tube, extending out from one of the small rings, is labeled proton source; the other end of the tube, near the other small ring, is labeled antiproton source. There are arrows representing the direction of particle travel, with blue arrows pointing toward the center of the tube from the proton source, and red arrows pointing toward the center of the tube from the antiproton source. The arrows meet at a box in the center of the tube structure. The box is labeled ‘Collision detector’ and has an explosion symbol on it."},{"sourceId":"fs-id1167066966450","filename":"CNX_HSPhysics_23_01_FermiLab2.jpg","relativePath":"media/CNX_HSPhysics_23_01_FermiLab2.jpg","alt":"An aerial view of the Fermi National Accelerator Laboratory is shown."}],"tables":[]}],"workedExamples":[],"snapLabs":[],"tipsAndFeatures":[],"summaryPoints":["The four fundamental forces are gravity, the electromagnetic force, the weak nuclear force, and the strong nuclear force.","A variety of particle accelerators have been used to explore the nature of subatomic particles and to test predictions of particle theories."],"glossary":[{"term":"carrier particle","termVi":"Hạt truyền tương tác (Boson chuẩn)","definition":"a virtual particle exchanged in the transmission of a fundamental force","definitionVi":"Hạt lượng tử trao đổi giữa các hạt vật chất để truyền lực (photon cho điện từ, gluon cho tương tác mạnh...).","memoryTipVi":"Mỗi lực cơ bản có hạt truyền tương tác riêng."},{"term":"colliding beam","termVi":"Chùm hạt đối đầu (Va chạm trực diện)","definition":"head-on collisions between particles moving in opposite directions","definitionVi":"Kỹ thuật cho hai chùm hạt lao ngược chiều đâm thẳng vào nhau để tối đa hóa năng lượng tạo hạt mới.","memoryTipVi":"Hiệu quả năng lượng cao hơn nhiều so với bắn vào bia đứng yên."},{"term":"cyclotron","termVi":"Máy gia tốc vòng Cyclotron","definition":"accelerator that uses fixed-frequency alternating electric fields and fixed magnets to accelerate particles in a circular spiral path","definitionVi":"Máy gia tốc dùng từ trường uốn hạt chạy theo đường xoắn ốc và điện trường xoay chiều để tăng tốc hạt.","memoryTipVi":"Do Ernest Lawrence chế tạo."},{"term":"Feynman diagram","termVi":"Giản đồ Feynman","definition":"a graph of time versus position that describes the exchange of virtual particles between subatomic particles","definitionVi":"Hình vẽ trực quan mô tả sự tương tác và trao đổi hạt truyền lực giữa các hạt hạ nguyên tử trong không–thời gian.","memoryTipVi":"Do Richard Feynman phát minh."},{"term":"graviton","termVi":"Hạt Graviton (hạt truyền lực hấp dẫn giả thuyết)","definition":"hypothesized particle exchanged between two particles of mass, transmitting the gravitational force between them","definitionVi":"Hạt lượng tử được dự đoán truyền tương tác hấp dẫn (hiện chưa quan sát trực tiếp được).","memoryTipVi":"Không khối lượng, spin bằng 2."},{"term":"particle physics","termVi":"Vật lý hạt cơ bản (Vật lý năng lượng cao)","definition":"the study of and the quest for those truly fundamental particles having no substructure","definitionVi":"Ngành vật lý nghiên cứu những viên gạch cấu trúc nhỏ nhất của vật chất và 4 tương tác cơ bản.","memoryTipVi":"Thí nghiệm tại các máy gia tốc khổng lồ như LHC (CERN)."},{"term":"pion","termVi":"Hạt Pion (π meson)","definition":"particle exchanged between nucleons, transmitting the strong nuclear force between them","definitionVi":"Hạt meson nhẹ truyền lực tương tác giữa các proton và neutron trong hạt nhân.","memoryTipVi":"Gồm 1 quark và 1 phản quark."},{"term":"quantum electrodynamics","termVi":"Điện động lực học lượng tử (QED)","definition":"the theory of electromagnetism on the particle scale","definitionVi":"Lý thuyết lượng tử mô tả tương tác điện từ giữa các hạt mang điện thông qua việc trao đổi photon.","memoryTipVi":"Lý thuyết có độ chính xác thực nghiệm cao nhất lịch sử vật lý."},{"term":"synchrotron","termVi":"Máy gia tốc đồng bộ Synchrotron","definition":"a version of a cyclotron in which the frequency of the alternating voltage and the magnetic field strength are increased as the beam particles are accelerated","definitionVi":"Máy gia tốc vòng cực lớn tăng đồng bộ từ trường khi hạt đạt năng lượng tương đối tính (như máy LHC dài 27 km tại CERN).","memoryTipVi":"LHC là một synchrotron."},{"term":"\\({\\text{W}}^{-}\\) boson","termVi":"Hạt Boson W⁻","definition":"negative carrier particle of the weak nuclear force","definitionVi":"Hạt mang điện âm khối lượng lớn truyền tương tác hạt nhân yếu.","memoryTipVi":"Tham gia vào phân rã β⁻."},{"term":"\\({\\text{W}}^{+}\\) boson","termVi":"Hạt Boson W⁺","definition":"positive carrier particle of the weak nuclear force","definitionVi":"Hạt mang điện dương truyền tương tác hạt nhân yếu.","memoryTipVi":"Phản hạt của W⁻."},{"term":"weak nuclear force","termVi":"Lực hạt nhân yếu (Tương tác yếu)","definition":"fundamental force responsible for particle decay","definitionVi":"Một trong 4 lực cơ bản, chịu trách nhiệm gây ra phân rã phóng xạ Beta (β).","memoryTipVi":"4 lực cơ bản từ mạnh → yếu: Mạnh > Điện từ > Yếu > Hấp dẫn."},{"term":"\\({\\text{Z}}^{0}\\) boson","termVi":"Hạt Boson Z⁰","definition":"neutral carrier particle of the weak nuclear force","definitionVi":"Hạt trung hòa về điện truyền tương tác hạt nhân yếu.","memoryTipVi":"Phát hiện tại CERN năm 1983."}],"assessments":[{"uid":"hsphys.ch23.sec01.q001","sourceId":"fs-id1167067012149","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Which of the four forces is responsible for radioactive decay?","images":[],"choices":[{"label":"a","text":"the electromagnetic force"},{"label":"b","text":"the gravitational force"},{"label":"c","text":"the strong nuclear force"},{"label":"d","text":"the weak nuclear force"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec01.q002","sourceId":"fs-id1167066854018","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"What force or forces exist between an electron and a proton?","images":[],"choices":[{"label":"a","text":"the strong nuclear force, the electromagnetic force, and gravity"},{"label":"b","text":"the weak nuclear force, the strong nuclear force, and gravity"},{"label":"c","text":"the weak nuclear force, the strong nuclear force, and the electromagnetic force"},{"label":"d","text":"the weak nuclear force, the electromagnetic force, and gravity"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec01.q003","sourceId":"fs-id1167063529914","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"What is the proposed carrier particle for the gravitational force?","images":[],"choices":[{"label":"a","text":"boson"},{"label":"b","text":"graviton"},{"label":"c","text":"gluon"},{"label":"d","text":"photon"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec01.q005","sourceId":"fs-id1167060128362","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"What type of particle accelerator uses fixed-frequency oscillating electric fields to accelerate particles?","images":[],"choices":[{"label":"a","text":"cyclotron"},{"label":"b","text":"synchrotron"},{"label":"c","text":"betatron"},{"label":"d","text":"Van de Graaff accelerator"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec01.q007","sourceId":"eip-id1166849635001","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Which of the four forces is responsible for the structure of galaxies?","images":[],"choices":[{"label":"a","text":"electromagnetic force"},{"label":"b","text":"gravity"},{"label":"c","text":"strong nuclear force"},{"label":"d","text":"weak nuclear force"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec01.q008","sourceId":"fs-id1167066948069","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"What forces does the inverse square law describe?","images":[],"choices":[{"label":"a","text":"the electromagnetic and weak nuclear force"},{"label":"b","text":"the electromagnetic force and strong nuclear force"},{"label":"c","text":"the electromagnetic force and gravity"},{"label":"d","text":"the strong nuclear force and gravity"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec01.q009","sourceId":"fs-id1167066843214","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Do the carrier particles explain the loss of mass in nuclear decay?","images":[],"choices":[{"label":"a","text":"no"},{"label":"b","text":"yes"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec01.q011","sourceId":"eip-id1166850077760","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Which of the four forces is responsible for ionic bonding?","images":[],"choices":[{"label":"a","text":"electromagnetic force"},{"label":"b","text":"gravity"},{"label":"c","text":"strong force"},{"label":"d","text":"weak nuclear force"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec01.q012","sourceId":"eip-id1166849388868","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"What type of particle accelerator uses oscillating electric fields to accelerate particles around a fixed radius track?","images":[],"choices":[{"label":"a","text":"LINAC"},{"label":"b","text":"synchrotron"},{"label":"c","text":"SLAC"},{"label":"d","text":"Van de Graaff accelerator"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec01.q013","sourceId":"fs-id1167063517238","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"The gravitational force is considered a very weak force. Yet, it is strong enough to hold Earth in orbit around the Sun. Explain this apparent disparity.","images":[],"choices":[{"label":"a","text":"At the level of the Earth-to-Sun distance, gravity is the strongest acting force because neither the strong nor the weak nuclear force exists at this distance."},{"label":"b","text":"At the level of the Earth-to-Sun distance, gravity is the strongest acting force because both the strong and the weak nuclear force is minimal at this distance."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec01.q014","sourceId":"fs-id1167066870588","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"True or FalseGiven that their carrier particles are massless, some may argue that the electromagnetic and gravitational forces should maintain the same value at all distances from their source. However, both forces decrease with distance at a rate of \\(\\frac{1}{r}\\)","images":[],"choices":[{"label":"a","text":"false"},{"label":"b","text":"true"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec01.q017","sourceId":"fs-id1167067255384","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Which of the following is not one of the four fundamental forces?","images":[],"choices":[{"label":"a","text":"gravity"},{"label":"b","text":"friction"},{"label":"c","text":"strong nuclear"},{"label":"d","text":"electromagnetic"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec01.q020","sourceId":"eip-id1166849329272","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What force or forces exist between a proton and a second proton?","images":[],"choices":[{"label":"a","text":"The weak electrostatic force and strong magnetic force"},{"label":"b","text":"The weak electrostatic and strong gravitational force"},{"label":"c","text":"The weak frictional force and strong gravitational force"},{"label":"d","text":"The weak nuclear force, the strong nuclear force, and the electromagnetic force"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec01.q021","sourceId":"fs-id1167063426316","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Why do people tend to be more aware of the gravitational and electromagnetic forces than the strong and weak nuclear forces?","images":[],"choices":[{"label":"a","text":"The gravitational and electromagnetic forces act at short ranges, while strong and weak nuclear forces act at comparatively long range."},{"label":"b","text":"The strong and weak nuclear forces act at short ranges, while gravitational and electromagnetic forces act at comparatively long range."},{"label":"c","text":"The strong and weak nuclear forces act between all objects, while gravitational and electromagnetic forces act between smaller objects."},{"label":"d","text":"The strong and weak nuclear forces exist in outer space, while gravitational and electromagnetic forces exist everywhere."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec01.q022","sourceId":"fs-id1167063531263","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"What fundamental force is responsible for the force of friction?","images":[],"choices":[{"label":"a","text":"the electromagnetic force"},{"label":"b","text":"the strong nuclear force"},{"label":"c","text":"the weak nuclear force"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec01.q024","sourceId":"fs-id1167063582786","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Which carrier particle is transmitted solely between nucleons?","images":[],"choices":[{"label":"a","text":"graviton"},{"label":"b","text":"photon"},{"label":"c","text":"pion"},{"label":"d","text":"W and Z bosons"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec01.q025","sourceId":"fs-id1167063867582","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Two particles of the same mass are traveling at the same speed but in opposite directions when they collide head-on.\nWhat is the final kinetic energy of this two-particle system?","images":[],"choices":[{"label":"a","text":"infinite"},{"label":"b","text":"the sum of the kinetic energies of the two particles"},{"label":"c","text":"zero"},{"label":"d","text":"the product of the kinetic energies of the two particles"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec01.q027","sourceId":"fs-id1167067054655","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"If the strong attractive force is the greatest of the four fundamental forces, are all masses fated to combine together at some point in the future? Explain.","images":[],"choices":[{"label":"a","text":"No, the strong attractive force acts only at incredibly small distances. As a result, only masses close enough to be within its range will combine."},{"label":"b","text":"No, the strong attractive force acts only at large distances. As a result, only masses far enough apart will combine."},{"label":"c","text":"Yes, the strong attractive force acts at any distance. As a result, all masses are fated to combine together at some point in the future."},{"label":"d","text":"Yes, the strong attractive force acts at large distances. As a result, all masses are fated tocombine together at some point in the future."}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":3,"keyEquationCount":0,"subsectionCount":3,"workedExampleCount":0,"snapLabCount":0,"glossaryCount":13,"assessmentCount":18}},{"uid":"hsphys.ch23.sec02","moduleId":"m54595","number":"23.2","slug":"quarks","title":"Quarks","isIntroduction":false,"learningObjectives":["Describe quarks and their relationship to other particles","Distinguish hadrons from leptons","Distinguish matter from antimatter","Describe the standard model of the atom","Define a Higgs boson and its importance to particle physics"],"bilingualGuide":{"notebookSummaryVi":"Mô hình Chuẩn (Standard Model): 6 hạt Quark (tạo proton uud & neutron udd), 6 hạt Lepton (electron, neutrino), Phản vật chất (Hủy cặp & Tạo cặp) và Hạt Boson Higgs.","wordProblemCues":[{"phraseEn":"proton (uud) & neutron (udd)","meaningVi":"Cấu tạo quark của proton (+1e) và neutron (0)","mathNotation":"u=+2/3e, d=-1/3e"}],"commonTrapsVi":["Electron là hạt cơ bản thuộc họ LEPTON (không cấu tạo từ quark!), còn Proton và Neutron là hạt tổ hợp (Baryon) cấu tạo từ 3 hạt quark!"]},"keyEquations":[],"subsections":[{"uid":"hsphys.ch23.sec02.sub01","title":"Quarks","summaryVi":null,"paragraphs":["“The first principles of the universe are atoms and empty space. Everything else is merely thought to exist…”","“… Further, the atoms are unlimited in size and number, and they are borne along with the whole universe in a vortex, and thereby generate all composite things—fire, water, air, earth. For even these are conglomerations of given atoms. And it because of their solidity that these atoms are impassive and unalterable.”","Diogenes Laertius (summarizing the views of Democritus, circa 460–370 B.C.)","The search for fundamental particles is nothing new. Atomists of the Greek and Indian empires, like Democritus of fifth century B.C., openly wondered about the most finite components of our universe. Though dormant for centuries, curiosity about the atomic nature of matter was reinvigorated by Rutherford’s gold foil experiment and the discovery of the nucleus. By the early 1930s, scientists believed they had fully determined the tiniest constituents of matter—in the form of the proton, neutron, and electron.","This would be only partially true. At present, scientists know that there are hundreds of particles not unlike our electron and nucleons, all making up what some have termed the particle zoo . While we are confident that the electron remains fundamental, it is surrounded by a plethora of similar sounding terms, like leptons, hadrons, baryons, and mesons. Even though not every particle is considered fundamental, they all play a vital role in understanding the intricate structure of our universe.","A fundamental particle is defined as a particle with no substructure and no finite size. According to the Standard Model , there are three types of fundamental particles: leptons, quarks, and carrier particles. As you may recall, carrier particles are responsible for transmitting fundamental forces between their interacting masses. Leptons are a group of six particles not bound by the strong nuclear force, of which the electron is one. As for quarks, they are the fundamental building blocks of a group of particles called hadrons , a group that includes both the proton and the neutron.","Now for a brief history of quarks . Quarks were first proposed independently by American physicists Murray Gell-Mann and George Zweig in 1963. Originally, three quark types—or flavors —were proposed with the names up ( u ), down ( d ), and strange ( s ).","At first, physicists expected that, with sufficient energy, we should be able to free quarks and observe them directly. However, this has not proved possible, as the current understanding is that the force holding quarks together is incredibly great and, much like a spring, increases in magnitude as the quarks are separated. As a result, when large energies are put into collisions, other particles are created—but no quarks emerge. With that in mind, there is compelling evidence for the existence of quarks. By 1967, experiments at the SLAC National Accelerator Laboratory scattering 20-GeV electrons from protons produced results like Rutherford had obtained for the nucleus nearly 60 years earlier. The SLAC scattering experiments showed unambiguously that there were three point-like (meaning they had sizes considerably smaller than the probe’s wavelength) charges inside the proton as seen in [Figure 23.2]. This evidence made all but the most skeptical admit that there was validity to the quark substructure of hadrons.","The inclusion of the strange quark with Zweig and Gell-Mann’s model concerned physicists. While the up and down quarks demonstrated fairly clear symmetry and were present in common fundamental particles like protons and neutrons, the strange quark did not have a counterpart of its own. This thought, coupled with the four known leptons at the time, caused scientists to predict that a fourth quark, yet to be found, also existed.","In 1974, two groups of physicists independently discovered a particle with this new quark, labeled charmed . This completed the second exotic quark pair, strange (s) and charmed (c). A final pair of quarks was proposed when a third pair of leptons was discovered in 1975. The existence of the bottom (b) quark and the top (t) quark was verified through experimentation in 1976 and 1995, respectively. While it may seem odd that so much time would elapse between the original quark discovery in 1967 and the verification of the top quark in 1995, keep in mind that each quark discovered had a progressively larger mass. As a result, each new quark has required more energy to discover.","One of the most confounding traits of quarks is their electric charge. Long assumed to be discrete, and specifically a multiple of the elementary charge of the electron, the electric charge of an individual quark is fractional and thus seems to violate a presumed tenet of particle physics. The fractional charge of quarks, which are \\(\\pm (\\frac{2}{3}){q}_{e}\\) and \\(\\pm (\\frac{1}{3}){q}_{e}\\), are the only structures found in nature with a nonintegral number of charge \\(q\\) . However, note that despite this odd construction, the fractional value of the quark does not violate the quantum nature of the charge. After all, free quarks cannot be found in nature, and all quarks are bound into arrangements in which an integer number of charge is constructed. [Table_23_03] shows the six known quarks, in addition to their antiquark components, as will be discussed later in this section.","While the term flavor is used to differentiate between types of quarks, the concept of color is more analogous to the electric charge in that it is primarily responsible for the force interactions between quarks. Note—Take a moment to think about the electrostatic force. It is the electric charge that causes attraction and repulsion. It is the same case here but with a color charge. The three colors available to a quark are red, green, and blue, with antiquarks having colors of anti-red (or cyan), anti-green (or magenta), and anti-blue (or yellow).","Why use colors when discussing quarks? After all, the quarks are not actually colored with visible light. The reason colors are used is because the properties of a quark are analogous to the three primary and secondary colors mentioned above. Just as different colors of light can be combined to create white, different colors of quark may be combined to construct a particle like a proton or neutron. In fact, for each hadron, the quarks must combine such that their color sums to white! Recall that two up quarks and one down quark construct a proton, as seen in [Figure 23.2]. The sum of the three quarks’ colors—red, green, and blue—yields the color white. This theory of color interaction within particles is called quantum chromodynamics , or QCD. As part of QCD, the strong nuclear force can be explained using color. In fact, some scientists refer to the color force, not the strong force, as one of the four fundamental forces. [Figure 23.2] is a Feynman diagram showing the interaction between two quarks by using the transmission of a colored gluon . Note that the gluon is also considered the charge carrier for the strong nuclear force.","Note that quark flavor may have any color. For instance, in [Figure 23.2], the down quark has a red color and a green color. In other words, colors are not specific to a particle quark flavor."],"figures":[{"sourceId":"fs-id1167067275298","filename":"CNX_HSPhysics_23_02_SLAC.jpg","relativePath":"media/CNX_HSPhysics_23_02_SLAC.jpg","alt":"The image shows a large blue sphere representing a proton with three small spheres within it. The three small spheres are labeled ‘u’, ‘u’, and ‘d’, and are colored blue, green, and red, respectively. These three smaller spheres represent up and down quarks. From the left to the right of the image are arrows representing the trajectory of electrons. Some of the electrons pass through the proton, while others are shown striking the quarks and scattering away."},{"sourceId":"fs-id1167066783814","filename":"CNX_HSPhysics_23_02_Color.jpg","relativePath":"media/CNX_HSPhysics_23_02_Color.jpg","alt":"The diagram shows two quarks, a down quark and a strange quark, traveling toward each other. As the down quark expels a gluon, it changes color from red to green. As the strange quark receives the gluon, it changes color from green to red. The gluon is colored red and magenta and is labeled ‘red-antigreen’."}],"tables":[{"sourceId":"Table_23_03","headers":["Flavor","Symbol","Antiparticle","Charge [1][2]"],"rows":[["Up","\\(u\\)","\\(\\bar{u}\\)","\\(\\pm \\frac{2}{3}{q}_{e}\\)"],["Down","\\(d\\)","\\(\\bar{d}\\)","\\(∓\\frac{1}{3}{q}_{e}\\)"],["Strange","\\(s\\)","\\(\\bar{s}\\)","\\(∓\\frac{1}{3}{q}_{e}\\)"],["Charmed","\\(c\\)","\\(\\bar{c}\\)","\\(\\pm \\frac{2}{3}{q}_{e}\\)"],["Bottom","\\(b\\)","\\(\\bar{b}\\)","\\(∓\\frac{1}{3}{q}_{e}\\)"],["Top","\\(t\\)","\\(\\bar{t}\\)","\\(\\pm \\frac{2}{3}{q}_{e}\\)"]]}]},{"uid":"hsphys.ch23.sec02.sub02","title":"Hadrons and Leptons","summaryVi":null,"paragraphs":["Particles can be revealingly grouped according to what forces they feel between them. All particles (even those that are massless) are affected by gravity since gravity affects the space and time in which particles exist. All charged particles are affected by the electromagnetic force, as are neutral particles that have an internal distribution of charge (such as the neutron with its magnetic moment). Special names are given to particles that feel the strong and weak nuclear forces. Hadrons are particles that feel the strong nuclear force, whereas leptons are particles that do not. All particles feel the weak nuclear force. This means that hadrons are distinguished by being able to feel both the strong and weak nuclear forces. Leptons and hadrons are distinguished in other ways as well. Leptons are fundamental particles that have no measurable size, while hadrons are composed of quarks and have a diameter on the order of 10 –15 m. Six particles, including the electron and neutrino , make up the list of known leptons. There are hundreds of complex particles in the hadron class, a few of which (including the proton and neutron) are listed in [Table_23_04].","There are many more leptons, mesons, and baryons yet to be discovered and measured. The purpose of trying to uncover the smallest indivisible things in existence is to explain the world around us through forces and the interactions between particles, galaxies and objects. This is why a handful of scientists devote their life’s work to smashing together small particles.","What internal structure makes a proton so different from an electron? The proton, like all hadrons, is made up of quarks. A few examples of hadron quark composition can be seen in [Figure 23.2]. As shown, each hadron is constructed of multiple quarks. As mentioned previously, the fractional quark charge in all four hadrons sums to the particle’s integral value. Also, notice that the color composition for each of the four particles adds to white. Each of the particles shown is constructed of up, down, and their antiquarks. This is not surprising, as the quarks strange, charmed, top, and bottom are found in only our most exotic particles.","You may have noticed that while the proton and neutron in [Figure 23.2] are composed of three quarks, both pions are comprised of only two quarks. This refers to a final delineation in particle structure. Particles with three quarks are called baryons . These are heavy particles that can decay into another baryon. Particles with only two quarks—a-quarkanti-quark pair—are called mesons . These are particles of moderate mass that cannot decay into the more massive baryons.","Before continuing, take a moment to view [Figure 23.2]. In this figure, you can see the strong force reimagined as a color force. The particles interacting in this figure are the proton and neutron, just as they were in [Figure 23.1]. This reenvisioning of the strong force as an interaction between colored quarks is the critical concept behind quantum chromodynamics."],"figures":[{"sourceId":"fs-id1167067132571","filename":"CNX_HSPhysics_23_02_Hadron.jpg","relativePath":"media/CNX_HSPhysics_23_02_Hadron.jpg","alt":"There are four pictures in this figure, each showing the structure of a hadron. The proton on the left is composed of three quarks (two up and one down). The colors of the quarks are blue, green, and red. The second picture is of a neutron, which is composed of three quarks (one up and two down). The colors of its quarks are green, blue, and red. The third image is of a positive pion, which is composed of two quarks (up and anti-down). The colors of its quarks are red and anti-red. The final picture is of a negative pion, which is composed of two quarks (anti-up and down). The colors of its quarks are green and anti-green. Underneath each quark is a summation of the quarks fractional charge. The summation of quark charges for both the proton and positive pion is +1. The summation of quark charges for the neutron is zero. The summation of quark charges for the negative pion is -1."},{"sourceId":"fs-id1167067139262","filename":"CNX_HSPhysics_23_02_Strong.jpg","relativePath":"media/CNX_HSPhysics_23_02_Strong.jpg","alt":"This is a complex picture of the relationship between individually colored quarks in the strong nuclear force, during the interaction between a proton and a neutron."}],"tables":[{"sourceId":"Table_23_04","headers":["Category","Particle Name","Symbol","Antiparticle","Rest Mass \\((MeV/{c}^{2})\\)","Mean Lifetime (s)"],"rows":[["Leptons","Electron","\\({e}^{-}\\)","\\({e}^{+}\\)","0.511","Stable"],["Neutrino (e)","\\({v}_{e}\\)","\\({\\bar{v}}_{e}\\)","\\(0\\,(7.0eV)\\)\n[1]","Stable"],["Muon","\\({\\mu}^{-}\\)","\\({\\mu}^{+}\\)","105.7","\\(2.20\\, \\times \\,{10}^{- 6}\\)"],["Neutrino (μ)","\\({v}_{\\mu}\\)","\\({\\bar{v}}_{\\mu}\\)","\\(0\\,(\\text{ [1]","Stable"],["Tau","\\({\\tau}^{-}\\)","\\({\\tau}^{+}\\)","1,777","\\(2.91 \\times {10}^{-6}\\)"],["Neutrino (τ)","\\({v}_{\\tau}\\)","\\({\\bar{v}}_{\\tau}\\)","\\(0\\,(\\text{ [1]","Stable"],["Hadrons – Mesons [2]","Pion","\\({\\pi}^{+}\\)","\\({\\pi}^{-}\\)","139.6","\\(2.60 \\times {10}^{-8}\\)"],["\\({\\pi}^{0}\\)","Self","135.0","\\(8.40 \\times {10}^{-17}\\)"],["Kaon","\\({K}^{+}\\)","\\({K}^{-}\\)","493.7","\\(1.24 \\times {10}^{-8}\\)"],["\\({K}^{0}\\)","\\({K}^{0}\\)","497.6","\\(0.90 \\times {10}^{-10}\\)"],["Eta","\\({η}^{0}\\)","Self","547.9","\\(2.53 \\times {10}^{-19}\\)"],["Hadrons – Baryons [3]","Proton","p","\\(\\bar{p}\\)","938.3","Stable"],["Neutron","n","\\(\\bar{n}\\)","939.6","882"],["Lambda","\\({\\text{Λ}}^{0}\\)","\\({\\bar{\\text{Λ}}}^{0}\\)","1,115.7","\\(2.63 \\times {10}^{- 10}\\)"],["Omega","\\({\\Omega}^{-}\\)","\\({\\Omega}^{+}\\)","1,672.5","\\(0.82 \\times {10}^{-10}\\)"]]}]},{"uid":"hsphys.ch23.sec02.sub03","title":"Matter and Antimatter","summaryVi":null,"paragraphs":["Antimatter was first discovered in the form of the positron , the positively charged electron. In 1932, American physicist Carl Anderson discovered the positron in cosmic ray studies. Through a cloud chamber modified to curve the trajectories of cosmic rays, Anderson noticed that the curves of some particles followed that of a negative charge, while others curved like a positive charge. However, the positive curve showed not the mass of a proton but the mass of an electron. This outcome is shown in [Figure 23.2] and suggests the existence of a positively charged version of the electron, created by the destruction of solar photons.","Antimatter is considered the opposite of matter. For most antiparticles, this means that they share the same properties as their original particles with the exception of their charge. This is why the positron can be considered a positive electron while the antiproton is considered a negative proton. The idea of an opposite charge for neutral particles (like the neutron) can be confusing, but it makes sense when considered from the quark perspective. Just as the neutron is composed of one up quark and two down quarks (of charge\n\\(+ \\frac{2}{3}\\)\nand\n\\(- \\frac{1}{3}\\)\n, respectively), the antineutron is composed of one antiup quark and two antidown quarks (of charge \\(- \\frac{2}{3}\\) and\n\\(+ \\frac{1}{3}\\)\n, respectively). While the overall charge of the neutron remains the same, its constituent particles do not!","A word about antiparticles: Like regular particles, antiparticles could function just fine on their own. In fact, a universe made up of antimatter may operate just as our own matter-based universe does. However, we do not know fully whether this is the case. The reason for this is annihilation . Annihilation is the process of destruction that occurs when a particle and its antiparticle interact. As soon as two particles (like a positron and an electron) coincide, they convert their masses to energy through the equation \\(E = m{c}^{2}\\) . This mass-to-energy conversion, which typically results in photon release, happens instantaneously and makes it very difficult for scientists to study antimatter. That said, scientists have had success creating antimatter through high-energy particle collisions. Both antineutrons and antiprotons were created through accelerator experiments in 1956, and an antihydrogen atom was even created at CERN in 1995! As referenced in [Figure 22.5], the annihilation of antiparticles is currently used in medical studies to determine the location of radioisotopes."],"figures":[{"sourceId":"fs-id1167067088105","filename":"CNX_HSPhysics_23_02_Positron.jpg","relativePath":"media/CNX_HSPhysics_23_02_Positron.jpg","alt":"The image shows two spirals originating from the same spot, with one directed upward and one directed downward. The spot from which the spirals originate is labeled ‘incident photon.’ The upward spiral is the positron, while the downward spiral is labeled ‘electron.’"}],"tables":[]},{"uid":"hsphys.ch23.sec02.sub04","title":"Completing the Standard Model of the Atom","summaryVi":null,"paragraphs":["The Standard Model of the atom refers to the current scientific view of the fundamental components and interacting forces of matter. The Standard Model ([Figure 23.2]) shows the six quarks that bind to form all hadrons, the six lepton particles already considered fundamental, the four carrier particles (or gauge bosons) that transmit forces between the leptons and quarks, and the recently added Higgs boson (which will be discussed shortly). This totals 17 fundamental particles, combinations of which are responsible for all known matter in our entire universe! When adding the antiquarks and antileptons, 31 components make up the Standard Model.","[Figure 23.2] shows all particles within the Standard Model of the atom. Not only does this chart divide all known particles by color-coded group, but it also provides information on particle stability. Note that the color-coding system in this chart is separate from the red, green, and blue color labeling system of quarks. The first three columns represent the three families of matter. The first column, considered Family 1, represents particles that make up normal matter, constructing the protons, neutrons, and electrons that make up the common world. Family 2, represented from the charm quark to the muon neutrino, is comprised of particles that are more massive. The leptons in this group are less stable and more likely to decay. Family 3, represented by the third column, are more massive still and decay more quickly. The order of these families also conveniently represents the order in which these particles were discovered.","The Standard Model also summarizes the fundamental forces that exist as particles interact. A closer look at the Standard Model, as shown in [Figure 23.2], reveals that the arrangement of carrier particles describes these interactions.","Each of the shaded areas represents a fundamental force and its constituent particles. The red shaded area shows all particles involved in the strong nuclear force, which we now know is due to quantum chromodynamics. The blue shaded area corresponds to the electromagnetic force, while the green shaded area corresponds to the weak nuclear force, which affects all quarks and leptons. The electromagnetic force and weak nuclear force are considered united by the electroweak force within the Standard Model. Also, because definitive evidence of the graviton is yet to be found, it is not included in the Standard Model.","One interesting feature of the Standard Model shown in [Figure 23.2] is that, while the gluon and photon have no mass, the Z and W bosons are very massive. What supplies these quickly moving particles with mass and not the gluons and photons? Furthermore, what causes some quarks to have more mass than others?","In the 1960s, British physicist Peter Higgs and others speculated that the W and Z bosons were actually just as massless as the gluon and photon. However, as the W and Z bosons traveled from one particle to another, they were slowed down by the presence of a Higgs field , much like a fish swimming through water. The thinking was that the existence of the Higgs field would slow down the bosons, causing them to decrease in energy and thereby transfer this energy to mass. Under this theory, all particles pass through the Higgs field, which exists throughout the universe. The gluon and photon travel through this field as well but are able to do so unaffected.","The presence of a force from the Higgs field suggests the existence of its own carrier particle, the Higgs boson. This theorized boson interacts with all particles but gluons and photons, transferring force from the Higgs field. Particles with large mass (like the top quark) are more likely to receive force from the Higgs boson.","While it is difficult to examine a field, it is somewhat simpler to find evidence of its carrier. On July 4, 2012, two groups of scientists at the LHC independently confirmed the existence of a Higgs-like particle. By examining trillions of proton–proton collisions at energies of 7 to 8 TeV, LHC scientists were able to determine the constituent particles that created the protons. In this data, scientists found a particle with similar mass, spin, parity, and interactions with other particles that matched the Higgs boson predicted decades prior. On March 13, 2013, the existence of the Higgs boson was tentatively confirmed by CERN. Peter Higgs and Francois Englert received the Nobel Prize in 2013 for the “theoretical discovery of a mechanism that contributes to our understanding of the origin and mass of subatomic particles.”"],"figures":[{"sourceId":"fs-id1167066870741","filename":"CNX_HSPhysics_23_02_Standard.jpg","relativePath":"media/CNX_HSPhysics_23_02_Standard.jpg","alt":"The image is of seventeen boxes, sixteen of which are in a four-by-four grid. (The seventeenth box, in yellow and off to the side, is of the Higgs boson.) Spheres in purple are quarks, spheres in green are leptons, and spheres in red are gauge bosons."},{"sourceId":"fs-id1167067218014","filename":"CNX_HSPhysics_23_02_Revised.jpg","relativePath":"media/CNX_HSPhysics_23_02_Revised.jpg","alt":"The sixteen boxes shown before are now shaded due to force. A red shade extends from the gluon and colors all purple quarks. A blue shade extends from the photon and colors all quarks and the first row of leptons (the electron, muon, and tau). A green shade extends from the Z and W bosons and colors all quarks and leptons. As the background colors overlap, the red shade appears brown, and the blue shade appears dark green."}],"tables":[]}],"workedExamples":[],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch23.sec02.feat01","type":"tip","title":"Tips for Success","text":"Note that a very important tenet of science occurred throughout the period of quark discovery. The charmed, bottom, and top quarks were all speculated on, and then were discovered some time later. Each of their discoveries helped to verify and strengthen the quark model. This process of speculation and verification continues to take place today and is part of what drives physicists to search for evidence of the graviton and Grand Unified Theory.","images":[]},{"uid":"hsphys.ch23.sec02.feat02","type":"tip","title":"Tips for Success","text":"Look for trends that exist within the Standard Model. Compare the charge of each particle. Compare the spin. How does mass relate to the model structure? Recognizing each of these trends and asking questions will yield more insight into the organization of particles and the forces that dictate particle relationships. Our understanding of the Standard Model is still young, and the questions you may have in analyzing the Standard Model may be some of the same questions that particle physicists are searching for answers to today!","images":[]},{"uid":"hsphys.ch23.sec02.feat03","type":"physics-in-action","title":"Particle Physicist","text":"If you have an innate desire to unravel life’s great mysteries and further understand the nature of the physical world, a career in particle physics may be for you!\nParticle physicists have played a critical role in much of society’s technological progress. From lasers to computers, televisions to space missions, splitting the atom to understanding the DNA molecule to MRIs and PET scans, much of our modern society is based on the work done by particle physicists.\nWhile many particle physicists focus on specialized tasks in the fields of astronomy and medicine, the main goal of particle physics is to further scientists’ understanding of the Standard Model. This may mean work in government, industry, or academics. Within the government, jobs in particle physics can be found within the National Institute for Standards and Technology, Department of Energy, NASA, and Department of Defense. Both the electronics and computer industries rely on the expertise of particle physicists. College teaching and research positions can also be potential career opportunities for particle physicists, though they often require some postgraduate work as a prerequisite. In addition, many particle physicists are employed to work on high-energy colliders. Domestic collider labs include the Brookhaven National Laboratory in New York, the Fermi National Accelerator Laboratory near Chicago, and the SLAC National Accelerator Laboratory operated by Stanford University. For those who like to travel, work at international collider labs can be found at the CERN facility in Switzerland in addition to institutes like the Budker Institute of Nuclear Physics in Russia, DESY in Germany, and KEK in Japan.\nShirley Jackson became the first African American woman to earn a Ph.D. from MIT back in 1973, and she went on to lead a highly successful career in the field of particle physics. Like Dr. Jackson, successful students of particle physics grow up with a strong curiosity in the world around them and a drive to continually learn more. If you are interested in exploring a career in particle physics, work to achieve good grades and SAT scores, and find time to read popular books on physics topics that interest you. While some math may be challenging, recognize that this is only a tool of physics and should not be considered prohibitive to the field. High-level work in particle physics often requires a Ph.D.; however, it is possible to find work with a master’s degree. Additionally, jobs in industry and teaching can be achieved with solely an undergraduate degree.","images":[]}],"summaryPoints":["There are three types of fundamental particles—leptons, quarks, and carrier particles.","Quarks come in six flavors and three colors and occur only in combinations that produce white.","Hadrons are thought to be composed of quarks, with baryons having three quarks and mesons having a quark and an antiquark.","Known particles can be divided into three major groups—leptons, hadrons, and carrier particles (gauge bosons).","All particles of matter have an antimatter counterpart that has the opposite charge and certain other quantum numbers. These matterantimatter pairs are otherwise very similar but will annihilate when brought together.","The strong force is carried by eight proposed particles called gluons, which are intimately connected to a quantum number called color—their governing theory is thus called quantum chromodynamics (QCD). Taken together, QCD and the electroweak theory are widely accepted as the Standard Model of particle physics."],"glossary":[{"term":"annihilation","termVi":"Sự hủy cặp hạt – phản hạt","definition":"the process of destruction that occurs when a particle and antiparticle interact","definitionVi":"Khi hạt gặp phản hạt của nó (như e⁻ + e⁺), cả hai biến mất hoàn toàn và chuyển hóa 100% khối lượng thành 2 photon tia gamma (E = 2mc²).","memoryTipVi":"Chuyển hóa hoàn toàn vật chất thành năng lượng."},{"term":"antimatter","termVi":"Phản vật chất","definition":"matter constructed of antiparticles; antimatter shares most of the same properties of regular matter, with charge being the only difference between many particles and their antiparticle analogues","definitionVi":"Vật chất cấu tạo từ các phản hạt (cùng khối lượng nhưng trái dấu điện tích với hạt thường).","memoryTipVi":"Gặp vật chất thường sẽ hủy nhau tạo năng lượng bức xạ thuần túy!"},{"term":"baryon","termVi":"Hạt Baryon (tổ hợp 3 Quark)","definition":"hadrons that always decay to another baryon","definitionVi":"Hạt nặng cấu tạo từ 3 hạt quark (như proton uud và neutron udd).","memoryTipVi":"Bary = nặng."},{"term":"bottom quark","termVi":"Quark đáy (b)","definition":"a quark flavor","definitionVi":"Quark thế hệ thứ ba mang điện tích -1/3 e.","memoryTipVi":"Bottom / Beauty quark."},{"term":"charmed quark","termVi":"Quark duyên (c)","definition":"a quark flavor, which is the counterpart of the strange quark","definitionVi":"Quark thế hệ thứ hai mang điện tích +2/3 e.","memoryTipVi":"Charm quark."},{"term":"color","termVi":"Điện tích màu (Đỏ, Lục, Lam trong QCD)","definition":"a property of quarks the relates to their interactions through the strong force","definitionVi":"Thuộc tính lượng tử của hạt quark và gluon đóng vai trò như \"điện tích\" của tương tác mạnh (không phải màu sắc thị giác!).","memoryTipVi":"3 quark trong proton có Đỏ + Lục + Lam = trung hòa màu (trắng)."},{"term":"down quark","termVi":"Quark xuống (d, điện tích -1/3 e)","definition":"the second lightest of all quarks","definitionVi":"Loại quark nhẹ thứ hai, mang điện tích -1/3 e.","memoryTipVi":"Neutron có 1 quark u và 2 quark d."},{"term":"flavor","termVi":"Hương (6 loại của Quark / Lepton)","definition":"quark type","definitionVi":"Tên gọi chỉ loại hạt quark (u, d, c, s, t, b) hoặc lepton.","memoryTipVi":"6 hương của quark."},{"term":"gluons","termVi":"Hạt Gluon (hạt truyền tương tác mạnh)","definition":"exchange particles of the nuclear strong force","definitionVi":"Hạt boson không khối lượng \"dán chặt\" (glue) các hạt quark lại với nhau bên trong proton và neutron.","memoryTipVi":"Glue = keo dán siêu mạnh!"},{"term":"hadron","termVi":"Hạt Hadron (hạt tổ hợp từ Quark)","definition":"particles composed of quarks that feel the strong and weak nuclear force","definitionVi":"Họ các hạt cấu tạo từ quark liên kết bởi lực mạnh — gồm Baryon (3 quark) và Meson (1 quark + 1 phản quark).","memoryTipVi":"Proton và neutron đều là Hadron (cụ thể là Baryon)."},{"term":"Higgs boson","termVi":"Hạt Boson Higgs","definition":"a massive particle that provides mass to the weak bosons and provides validity to the theory that carrier particles are identical under certain circumstances","definitionVi":"Hạt cơ bản được phát hiện tại CERN năm 2012, xác nhận sự tồn tại của trường Higgs tạo ra khối lượng cho các hạt cơ bản.","memoryTipVi":"Mảnh ghép cuối cùng hoàn thiện Mô hình Chuẩn."},{"term":"Higgs field","termVi":"Trường Higgs","definition":"the field through which all fundamental particles travel that provides them varying mass through the transport of the Higgs boson","definitionVi":"Trường lượng tử tràn ngập khắp vũ trụ; các hạt cơ bản tương tác với trường này để có khối lượng nghỉ.","memoryTipVi":"Photon không tương tác với trường Higgs nên không có khối lượng nghỉ."},{"term":"lepton","termVi":"Hạt Lepton (hạt cơ bản nhẹ, không chịu lực mạnh)","definition":"fundamental particles that do not feel the nuclear strong force","definitionVi":"Họ 6 hạt cơ bản KHÔNG cấu tạo từ quark (gồm electron, muon, tau và 3 hạt neutrino tương ứng).","memoryTipVi":"Electron là hạt Lepton quen thuộc nhất!"},{"term":"meson","termVi":"Hạt Meson (1 Quark + 1 Phản quark)","definition":"hadrons that can decay to leptons and leave no hadrons","definitionVi":"Hạt có khối lượng trung bình cấu tạo từ một cặp quark và phản quark.","memoryTipVi":"Không bền, phân rã rất nhanh."},{"term":"pair production","termVi":"Sự tạo cặp hạt – phản hạt","definition":"the creation of a particle and antiparticle, commonly an electron and positron, due to the annihilation of a photon","definitionVi":"Quá trình ngược với hủy cặp: một photon năng lượng rất cao biến đổi thành một cặp hạt và phản hạt (như e⁻ + e⁺).","memoryTipVi":"Minh chứng trực tiếp năng lượng biến thành khối lượng (m = E/c²)!"},{"term":"positron","termVi":"Hạt Positron (e⁺ — Phản hạt của electron)","definition":"a particle of antimatter that has the properties of a positively charged electron","definitionVi":"Phản hạt của electron: có cùng khối lượng với electron nhưng mang điện tích DƯƠNG (+e).","memoryTipVi":"Ứng dụng trong máy chụp cắt lớp y khoa PET (Positron Emission Tomography)!"},{"term":"quantum chromodynamics","termVi":"Sắc động lực học lượng tử (QCD)","definition":"the theory of color interaction between quarks that leads to understanding of the nuclear strong force","definitionVi":"Lý thuyết lượng tử mô tả tương tác mạnh giữa các hạt quark và gluon thông qua điện tích màu.","memoryTipVi":"Chromo = màu."},{"term":"quark","termVi":"Hạt Quark","definition":"an elementary particle and fundamental constituent of matter that is a substructure of hadrons","definitionVi":"Hạt cơ bản mang điện tích phân số (+2/3 e hoặc -1/3 e) kết hợp tạo thành proton và neutron.","memoryTipVi":"Proton = uud (+2/3 + 2/3 - 1/3 = +1); Neutron = udd (+2/3 - 1/3 - 1/3 = 0)!"},{"term":"Standard Model","termVi":"Mô hình Chuẩn (Standard Model)","definition":"an organization of fundamental particles and forces that is a result of quantum chromodynamics and electroweak theory","definitionVi":"Khung lý thuyết phân loại toàn bộ các hạt cơ bản đã biết (6 Quark, 6 Lepton, các Boson truyền lực và hạt Higgs).","memoryTipVi":"Bảng tuần hoàn của thế giới hạ nguyên tử!"},{"term":"strange quark","termVi":"Quark lạ (s)","definition":"the third lightest of all quarks","definitionVi":"Quark thế hệ thứ hai mang điện tích -1/3 e.","memoryTipVi":"Tạo nên các hạt lạ trong tia vũ trụ."},{"term":"top quark","termVi":"Quark đỉnh (t)","definition":"a quark flavor","definitionVi":"Hạt cơ bản nặng nhất trong Mô hình Chuẩn (nặng ngang cả một nguyên tử Vàng!).","memoryTipVi":"Mang điện tích +2/3 e."},{"term":"up quark","termVi":"Quark lên (u, điện tích +2/3 e)","definition":"the lightest of all quarks","definitionVi":"Loại quark nhẹ nhất, mang điện tích +2/3 e.","memoryTipVi":"Proton có 2 quark u và 1 quark d."}],"assessments":[{"uid":"hsphys.ch23.sec02.q001","sourceId":"fs-id1167067253541","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"In what particle were quarks originally discovered?","images":[],"choices":[{"label":"a","text":"the electron"},{"label":"b","text":"the neutron"},{"label":"c","text":"the proton"},{"label":"d","text":"the photon"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec02.q005","sourceId":"fs-id1167063599486","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Does antimatter exist?","images":[],"choices":[{"label":"a","text":"no"},{"label":"b","text":"yes"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec02.q009","sourceId":"fs-id1167066783790","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"What fundamental property is provided by particle interaction with the Higgs boson?","images":[],"choices":[{"label":"a","text":"charge"},{"label":"b","text":"mass"},{"label":"c","text":"spin"},{"label":"d","text":"color"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec02.q011","sourceId":"eip-id1166851026039","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"What particles were launched into the proton during the original discovery of the quark?","images":[],"choices":[{"label":"a","text":"bosons"},{"label":"b","text":"electrons"},{"label":"c","text":"neutrons"},{"label":"d","text":"photons"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec02.q012","sourceId":"fs-id1167061202767","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"How does the charge of an individual quark determine hadron structure?","images":[],"choices":[{"label":"a","text":"Since the hadron must have an integral value, the individual quarks must be combined such that the average of their charges results in the value of a quark."},{"label":"b","text":"Since the hadron must have an integral value, the individual atoms must be combined such that the sum of their charges is less than zero."},{"label":"c","text":"The individual quarks must be combined such that the product of their charges is equal to the total charge of the hadron structure."},{"label":"d","text":"Since the hadron must have an integral value of charge, the individual quarks must be combined such that the sum of their charges results in an integral value."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec02.q013","sourceId":"fs-id1167063837786","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Why do leptons not feel the strong nuclear force?","images":[],"choices":[{"label":"a","text":"Gluons are the carriers of the strong nuclear force that interacts between quarks through color interactions, but leptons are constructed of quarks that do not have gluons."},{"label":"b","text":"Gluons are the carriers of the strong nuclear force that interacts between quarks through mass interactions, but leptons are not constructed of quarks and are not massive."},{"label":"c","text":"Gluons are the carriers of the strong nuclear force that interacts between quarks through mass interactions, but leptons are constructed of the quarks that are not massive."},{"label":"d","text":"Gluons are the carriers of the strong nuclear force that interacts between quarks through color interactions, but leptons are not constructed of quarks, nor do they have color constituents."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec02.q014","sourceId":"fs-id1167063894582","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"What property commonly distinguishes antimatter from its matter analogue?","images":[],"choices":[{"label":"a","text":"mass"},{"label":"b","text":"charge"},{"label":"c","text":"energy"},{"label":"d","text":"speed"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec02.q015","sourceId":"fs-id1167063577811","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Can the Standard Model change as new information is gathered?","images":[],"choices":[{"label":"a","text":"yes"},{"label":"b","text":"no"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec02.q016","sourceId":"fs-id1167067202185","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"What is the relationship between the Higgs field and the Higgs boson?","images":[],"choices":[{"label":"a","text":"The Higgs boson is the carrier that transfers force for the Higgs field."},{"label":"b","text":"The Higgs field is the time duration over which the Higgs particles transfer force to the other particles."},{"label":"c","text":"The Higgs field is the magnitude of momentum transferred by the Higgs particles to the other particles."},{"label":"d","text":"The Higgs field is the magnitude of torque transfers by the Higgs particles on the other particles."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec02.q017","sourceId":"eip-id1166848780483","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"What were the original three flavors of quarks discovered?","images":[],"choices":[{"label":"a","text":"up, down, and charm"},{"label":"b","text":"up, down, and bottom"},{"label":"c","text":"up, down, and strange"},{"label":"d","text":"up, down, and top"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec02.q018","sourceId":"eip-id1166851278174","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Protons are more massive than electrons. The three quarks in the proton account for only a small amount of this mass difference. What accounts for the remaining excess mass in protons compared to electrons?","images":[],"choices":[{"label":"a","text":"The highly energetic gluons connecting the quarks account for the remaining excess mass in protons compared to electrons."},{"label":"b","text":"The highly energetic photons connecting the quarks account for the remaining excess mass in protons compared to electrons."},{"label":"c","text":"The antiparallel orientation of the quarks present in a proton accounts for the remaining excess mass in protons compared to electrons."},{"label":"d","text":"The parallel orientation of the quarks present in a proton accounts for the remaining excess mass in protons compared to electrons."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec02.q020","sourceId":"fs-id1167067034338","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Why are mesons considered unstable?","images":[],"choices":[{"label":"a","text":"Mesons are composites of two antiparticles that quickly annihilate each other."},{"label":"b","text":"Mesons are composites of two particles that quickly annihilate each other."},{"label":"c","text":"Mesons are composites of a particle and antiparticle that quickly annihilate each other."},{"label":"d","text":"Mesons are composites of two particles and one antiparticle that quickly annihilate each other."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec02.q021","sourceId":"fs-id1167066806591","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Does antimatter have a negative mass?","images":[],"choices":[{"label":"a","text":"No, antimatter does not have a negative mass."},{"label":"b","text":"Yes, antimatter does have a negative mass."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec02.q023","sourceId":"fs-id1167063914801","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"How were particle collisions used to provide evidence of the Higgs boson?","images":[],"choices":[{"label":"a","text":"Because some particles do not contain the Higgs boson, the collisions of such particles will cause their destruction."},{"label":"b","text":"Because only the charged particles contain the Higgs boson, the collisions of such particles will cause their destruction and will expel the Higgs boson."},{"label":"c","text":"Because all particles with mass contain the Higgs boson, the collisions of such particles will cause their destruction and will absorb the Higgs boson."},{"label":"d","text":"Because all particles with mass contain the Higgs boson, the collisions of such particles will cause their destruction and will expel the Higgs boson."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec02.q024","sourceId":"eip-id1166851317235","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Explain how the combination of a quark and antiquark can result in the creation of a hadron.","images":[],"choices":[{"label":"a","text":"The combination of a quark and antiquark can result in a particle with an integer charge and color of white, therefore satisfying the properties for a hadron."},{"label":"b","text":"The combination of a quark and antiquark must result in a particle with a negative charge and color of white, therefore satisfying the properties for a hadron."},{"label":"c","text":"The combination of a quark and antiquark can result in a particle with an integer charge and color that is not white, therefore satisfying the properties for a hadron."},{"label":"d","text":"The combination of a quark and antiquark can result in particle with a fractional charge and color that is not white, therefore satisfying the properties for a hadron."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec02.q025","sourceId":"fs-id1167067157951","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"To what color must quarks combine for a particle to be constructed?","images":[],"choices":[{"label":"a","text":"black"},{"label":"b","text":"green"},{"label":"c","text":"red"},{"label":"d","text":"white"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec02.q026","sourceId":"fs-id1167067145996","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What type of hadron is always constructed partially of an antiquark?","images":[],"choices":[{"label":"a","text":"baryon"},{"label":"b","text":"lepton"},{"label":"c","text":"meson"},{"label":"d","text":"photno"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec02.q027","sourceId":"fs-id1167063589633","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What particle is typically released when two particles annihilate?","images":[],"choices":[{"label":"a","text":"graviton"},{"label":"b","text":"antimatter"},{"label":"c","text":"pion"},{"label":"d","text":"photno"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec02.q028","sourceId":"fs-id1167063693100","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Which of the following categories is not one of the three main categories of the Standard Model?","images":[],"choices":[{"label":"a","text":"gauge bosons"},{"label":"b","text":"hadrons"},{"label":"c","text":"leptons"},{"label":"d","text":"quarks"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec02.q029","sourceId":"fs-id1167067032745","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Analysis of what particles began the search for the Higgs boson?","images":[],"choices":[{"label":"a","text":"W and Z bosons"},{"label":"b","text":"up and down quarks"},{"label":"c","text":"mesons and baryons"},{"label":"d","text":"neutrinos and photons"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec02.q031","sourceId":"fs-id1167067086834","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"What two features of quarks determine the structure of a particle?","images":[],"choices":[{"label":"a","text":"the color and charge of individual quarks"},{"label":"b","text":"the color and size of individual quarks"},{"label":"c","text":"the charge and size of individual quarks"},{"label":"d","text":"the charge and mass of individual quarks"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec02.q032","sourceId":"fs-id1167067174757","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"What fundamental force does quantum chromodynamics describe?","images":[],"choices":[{"label":"a","text":"the weak nuclear force"},{"label":"b","text":"the strong nuclear force"},{"label":"c","text":"the electromagnetic force"},{"label":"d","text":"the gravitational force"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec02.q033","sourceId":"fs-id1167063463872","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Is it possible for a baryon to be constructed of two quarks and an antiquark?","images":[],"choices":[{"label":"a","text":"Yes, the color of the three particles would be able to sum to white."},{"label":"b","text":"No, the color of the three particles would not be able to sum to white."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec02.q034","sourceId":"fs-id1167067273077","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Can baryons be more massive than mesons?","images":[],"choices":[{"label":"a","text":"no"},{"label":"b","text":"yes"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec02.q036","sourceId":"fs-id1167066870760","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Does a neutron have an antimatter counterpart?","images":[],"choices":[{"label":"a","text":"No, the antineutron does not exist."},{"label":"b","text":"Yes, the antineutron does exist."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec02.q038","sourceId":"fs-id1167066810056","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"Which particles in the Standard Model account for the majority of matter with which we are familiar?","images":[],"choices":[{"label":"a","text":"particles in fourth column of the Standard Model"},{"label":"b","text":"particles in third column of the Standard Model"},{"label":"c","text":"particles in the second column of the Standard Model"},{"label":"d","text":"particles in the first column of the Standard Model"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec02.q041","sourceId":"fs-id1167066787347","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"In this image, how does the emission of the gluon cause the down quark to change from a red color to a green color?","images":[{"sourceId":"fs-id1164565008746","filename":"CNX_HSPhysics_23_02_Color.jpg","relativePath":"media/CNX_HSPhysics_23_02_Color.jpg","alt":"The figure has two equations R right arrow G plus R G and R G plus G right arrow R. A vertical time axis and horizontal x-axis or distance is in the bottom left hand corner of the schematic relating to these equations. Inside of the axis are five spheres, three in a diagonal pattern are red with two green ones on either side of the filled diagonal. The two equations are showing the process by which the R, red d sphere, and G, green s sphere, react with a creation of the R G, red g sphere, by the R, red d sphere, to create G, green d sphere. The other initial G, green s sphere, reacts with the newly created R G sphere to create R, red s sphere."}],"choices":[{"label":"a","text":"The emitted red gluon is made up of a green and a red color. As a result, the down quark changes from a red color to a green color."},{"label":"b","text":"The emitted red gluon is made up of an anti-green and an anti-red color. As a result, the down quark changes from a red color to a green color."},{"label":"c","text":"The emitted red gluon is made up of a green and an anti-red color. As a result, the down quark changes from a red color to a green color."},{"label":"d","text":"The emitted red gluon is made up of an anti-green and a red color. As a result, the down quark changes from a red color to a green color."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec02.q042","sourceId":"fs-id1167067123854","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"Neutrinos are much more difficult for scientists to find when compared to other hadrons and leptons. Why is this?","images":[],"choices":[{"label":"a","text":"Neutrinos are hadrons, and they lack charge."},{"label":"b","text":"Neutrinos are not hadrons, and they lack charge."},{"label":"c","text":"Neutrinos are hadrons, and they have positive charge."},{"label":"d","text":"Neutrinos are not hadrons, and they have a positive charge."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec02.q045","sourceId":"fs-id1167063836416","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"The term force carrier particle is shorthand for the scientific term vector gauge boson . From that perspective, can the Higgs boson truly be considered a force carrier particle ?","images":[],"choices":[{"label":"a","text":"No, the mass quality provided by the Higgs boson is a scalar quantity."},{"label":"b","text":"Yes, the mass quality provided by the Higgs boson results in a change of particles direction."}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":5,"keyEquationCount":0,"subsectionCount":4,"workedExampleCount":0,"snapLabCount":0,"glossaryCount":22,"assessmentCount":29}},{"uid":"hsphys.ch23.sec03","moduleId":"m54588","number":"23.3","slug":"the-unification-of-forces","title":"The Unification of Forces","isIntroduction":false,"learningObjectives":["Define a grand unified theory and its importance","Explain the evolution of the four fundamental forces from the Big Bang onward","Explain how grand unification theories can be tested"],"bilingualGuide":{"notebookSummaryVi":"Lịch sử tiến hóa Vũ trụ từ Vụ Nổ Lớn (Big Bang) và hành trình Thống nhất 4 lực cơ bản tiến tới Lý thuyết Vạn vật (Theory of Everything — TOE).","wordProblemCues":[{"phraseEn":"electroweak & GUT & TOE","meaningVi":"Các bậc thống nhất lực cơ bản ở năng lượng cao","mathNotation":"Unification"}],"commonTrapsVi":["Lý thuyết Điện yếu (thống nhất Điện từ + Yếu) đã được chứng minh thực nghiệm, còn GUT và TOE vẫn đang được nghiên cứu kiểm chứng!"]},"keyEquations":[],"subsections":[{"uid":"hsphys.ch23.sec03.sub01","title":"Understanding the Grand Unified Theory","summaryVi":null,"paragraphs":["Present quests to show that the four basic forces are different manifestations of a single unified force that follow a long tradition. In the nineteenth century, the distinct electric and magnetic forces were shown to be intimately connected and are now collectively called the electromagnetic force. More recently, the weak nuclear force was united with the electromagnetic force. As shown in [Figure 23.3], carrier particles transmit three of the four fundamental forces in very similar ways. With these considerations in mind, it is natural to suggest that a theory may be constructed in which the strong nuclear, weak nuclear, and electromagnetic forces are all unified. The search for a correct theory linking the forces, called the Grand Unified Theory (GUT) , is explored in this section.","In the 1960s, the electroweak theory was developed by Steven Weinberg, Sheldon Glashow, and Abdus Salam. This theory proposed that the electromagnetic and weak nuclear forces are identical at sufficiently high energies. At lower energies, like those in our present-day universe, the two forces remain united but manifest themselves in different ways. One of the main consequences of the electroweak theory was the prediction of three short-range carrier particles, now known as the \\({W}^{+},\\) \\({W}^{-},\\)\nand \\({\\text{Z}}^{0}\\) bosons. Not only were three particles predicted, but the mass of each \\({\\text{W}}^{+}\\) and \\({\\text{W}}^{-}\\) boson was predicted to be 81 GeV/ c 2 , and that of the \\({\\text{Z}}^{0}\\) boson was predicted to be 90 GeV/ c 2 . In 1983, these carrier particles were observed at CERN with the predicted characteristics, including masses having those predicted values as given in [Figure 23.2].","How can forces be unified? They are definitely distinct under most circumstances. For example, they are carried by different particles and have greatly different strengths. But experiments show that at extremely short distances and at extremely high energies, the strengths of the forces begin to become more similar, as seen in [Figure 23.3].","As discussed earlier, the short ranges and large masses of the weak carrier bosons require correspondingly high energies to create them. Thus, the energy scale on the horizontal axis of [Figure 23.3] also corresponds to shorter and shorter distances (going from left to right), with 100 GeV corresponding to approximately 10 -18 m, for example. At that distance, the strengths of the electromagnetic and weak nuclear forces are the same. To test this, energies of about 100 GeV are put into the system. When this occurs, the \\({\\text{W}}^{+}\\), \\({\\text{W}}^{-}\\), and \\({\\text{Z}}^{0}\\) carrier particles are created and released. At those and higher energies, the masses of the carrier particles become less and less relevant, and the \\({\\text{Z}}^{0}\\) boson in particular resembles the massless, chargeless photon. As further energy is added, the \\({\\text{W}}^{+}\\), \\({\\text{W}}^{-}\\), and \\({\\text{Z}}^{0}\\) particles are further transformed into massless carrier particles even more similar to photons and gluons.","The extremely short distances and high energies at which the electroweak force becomes identical with the strong nuclear force are not reachable with any conceivable human-built accelerator. At energies of about 10 14 GeV (16,000 J per particle), distances of about 10 –30 m can be probed. Such energies are needed to test the theory directly, but these are about 10 10 times higher than the maximum energy associated with the LHC, and the distances are about 10 12 smaller than any structure we have direct knowledge of. This would be the realm of various GUTs, of which there are many, since there is no constraining evidence at these energies and distances. Past experience has shown that anytime you probe so many orders of magnitude further, you find the unexpected.","While direct evidence of a GUT is not presently possible, that does not rule out the ability to assess a GUT through an indirect process. Current GUTs require various other events as a consequence of their theory. Some GUTs require the existence of magnetic monopoles, very massive individual north- and south-pole particles, which have not yet been proven to exist, while others require the use of extra dimensions. However, not all theories result in the same consequences. For example, disproving the existence of magnetic monopoles will not disprove all GUTs. Much of the science we accept in our everyday lives is based on different models, each with their own strengths and limitations. Although a particular model may have drawbacks, that does not necessarily mean that it should be discounted completely.","One consequence of GUTs that can theoretically be assessed is proton decay . Multiple current GUTs hypothesize that the stable proton should actually decay at a lifetime of 10 31 years. While this time is incredibly large (keep in mind that the age of the universe is less than 14 billion years), scientists at the Super-Kamiokande in Japan have used a 50,000-ton tank of water to search for its existence. The decay of a single proton in the Super-Kamiokande tank would be observed by a detector, thereby providing support for the predicting GUT model. However, as of 2014, 17 years into the experiment, decay is yet to be found. This time span equates to a minimum limit on proton life of \\(5.9\\, \\times \\,{10}^{33}\\) years. While this result certainly does not support many grand unifying theories, an acceptable model may still exist."],"figures":[{"sourceId":"fs-id1167063659712","filename":"CNX_HSPhysics_23_03_WeakFeyn.jpg","relativePath":"media/CNX_HSPhysics_23_03_WeakFeyn.jpg","alt":"The diagram shows an electron and electron neutrino traveling upward toward each other. As the electron expels a Z boson to the right, it is projected upward and to the left. The boson is received by the electron neutrino on the right. As a result, this particle is projected upward and to the right."},{"sourceId":"fs-id1167067317741","filename":"CNX_HSPhysics_23_03_GUT.jpg","relativePath":"media/CNX_HSPhysics_23_03_GUT.jpg","alt":"This graph plots the strengths of different forces (on the vertical axis) against their energies (on the horizontal axis). The graph shows a series of distinct lines, labeled gravity, weak nuclear, electromagnetic (EM), and strong nuclear, converging from the left to the right. The lines labeled EM and weak nuclear converge at an energy of 100 GeV and form a new line labeled electroweak. The lines labeled electroweak and strong nuclear converge at 1015 GeV. The location of their convergence is labeled GUT. The lines labeled strong nuclear and gravity converge at 1019 GeV. The location of their convergence is labeled TOE (Theory of Everything). The gravity line always trends upward as energy increases, while the line labeled strong nuclear always trends downward. Prior to their convergence, the EM line trended downward while the weak nuclear line trended upward. After their convergence, the electroweak line remained relatively horizontal."}],"tables":[]},{"uid":"hsphys.ch23.sec03.sub02","title":"The Standard Model and the Big Bang","summaryVi":null,"paragraphs":["Nature is full of examples where the macroscopic and microscopic worlds intertwine. Newton realized that the nature of gravity on Earth that pulls an apple to the ground could explain the motion of the moon and planets so much farther away. Decays of tiny nuclei explain the hot interior of the Earth. Fusion of nuclei likewise explains the energy of stars. Today, the patterns in particle physics seem to be explaining the evolution and character of the universe. And the nature of the universe has implications for unexplored regions of particle physics.","In 1929, Edwin Hubble observed that all but the closest galaxies surrounding our own had a red shift in their hydrogen spectra that was proportional to their distance from us. Applying the Doppler Effect, Hubble recognized that this meant that all galaxies were receding from our own, with those farther away receding even faster. Knowing that our place in the universe was no more unique than any other, the implication was clear: The space within the universe itself was expanding. Just like pen marks on an expanding balloon, everything in the universe was accelerating away from everything else.","[Figure 23.3] shows how the recession of galaxies looks like the remnants of a gigantic explosion, the famous Big Bang . Extrapolating backward in time, the Big Bang would have occurred between 13 and 15 billion years ago, when all matter would have been at a single point. From this, questions instantly arise. What caused the explosion? What happened before the Big Bang? Was there a before, or did time start then? For our purposes, the biggest question relating to the Big Bang is this: How does the Big Bang relate to the unification of the fundamental forces?","To fully understand the conditions of the very early universe, recognize that as the universe contracts to the size of the Big Bang, changes will occur. The density and temperature of the universe will increase dramatically. As particles become closer together, they will become too close to exist as we know them. The high energies will create other, more unusual particles to exist in greater abundance. Knowing this, let’s move forward from the start of the universe, beginning with the Big Bang, as illustrated in [Figure 23.3].","The Planck Epoch \\((0 \\to {10}^{-43}s)\\) —Though scientists are unable to model the conditions of the Planck Epoch in the laboratory, speculation is that at this time compressed energy was great enough to reach the immense \\({10}^{19}\\) GeV necessary to unify gravity with all other forces. As a result, modern cosmology suggests that all four forces would have existed as one force, a hypothetical superforce as suggested by the Theory of Everything .","The Grand Unification Epoch \\(({10}^{-43} \\to {10}^{-36}s)\\) —As the universe expands, the temperatures necessary to maintain the superforce decrease. As a result, gravity separates, leaving the electroweak and strong nuclear forces together. At this time, the electromagnetic, weak, and strong forces are identical, matching the conditions requested in the Grand Unification Theory.","The Inflationary Epoch \\(({10}^{- 36} \\to {10}^{- 32}s)\\) —The separation of the strong nuclear force from the electroweak force during this time is thought to have been responsible for the massive inflation of the universe. Corresponding to the steep diagonal line on the left side of [Figure 23.3], the universe may have expanded by a factor of \\({10}^{50}\\) or more in size. In fact, the expansion was so great during this time that it actually occurred faster than the speed of light! Unfortunately, there is little hope that we may be able to test the inflationary scenario directly since it occurs at energies near \\({10}^{14}\\) GeV, vastly greater than the limits of modern accelerators.","The Electroweak Epoch \\(({10}^{-32} \\to {10}^{-11}s)\\) —Now separated from both gravity and the strong nuclear force, the electroweak force exists as a singular force during this time period. As stated earlier, scientists are able to create the energies at this stage in the universe’s expansion, needing only 100 GeV, as shown in [Figure 23.3]. W and Z bosons, as well as the Higgs boson, are released during this time.","The Quark Era \\(({10}^{-11} \\to {10}^{-6}s)\\) —During the Quark Era, the universe has expanded and temperatures have decreased to the point at which all four fundamental forces have separated. Additionally, quarks began to take form as energies decreased.","As the universe expanded, further eras took place, allowing for the existence of hadrons, leptons, and photons, the fundamental particles of the standard model. Eventually, in nucleosynthesis, nuclei would be able to form, and the basic building blocks of atomic matter could take place. Using particle accelerators, we are very much working backwards in an attempt to understand the universe. It is encouraging to see that the macroscopic conditions of the Big Bang align nicely with our submicroscopic particle theory."],"figures":[{"sourceId":"fs-id1167063476434","filename":"CNX_HSPhysics_23_03_Expansion.jpg","relativePath":"media/CNX_HSPhysics_23_03_Expansion.jpg","alt":"The drawing shows galaxies fleeing from the center of the image, labeled MW for Milky Way. Galaxies further from the center have longer arrows pointing outward than galaxies near the center. This shows that the universe is expanding."},{"sourceId":"fs-id1167067075540","filename":"CNX_HSPhysics_23_03_Timeline.jpg","relativePath":"media/CNX_HSPhysics_23_03_Timeline.jpg","alt":"The timeline runs left to right, from 10-43 seconds to 15x1010 years (labeled as ‘now’). Concurrent with the timeline are energy levels, which begin at 1019 GeV. Additional information includes eras of evolution and the types of particles that are produced within each era. The right side of the image shows small galaxies, corresponding to a time period on the order of 109 years."}],"tables":[]},{"uid":"hsphys.ch23.sec03.sub03","title":"Performance Task","summaryVi":null,"paragraphs":["Communication is an often overlooked and useful skill for a scientist, especially in a competitive field where financial resources are limited. Scientists are often required to explain their findings or the relevance of their work to agencies within the government in order to maintain funding to continue their research. Let’s say you are an ambitious young particle physicist, heading an expensive project, and you need to justify its existence to the appropriate funding agency. Write a brief paper (about one page) explaining why molecular-level structure is important in the functioning of designed materials in a specific industry.","One example would be explaining how flexible but durable materials are made up of long-chained molecules and how this is useful for finding more environmentally friendly alternatives to plastics. Another example is explaining why electrically conductive materials are often made of metal and how this is useful for developing better batteries."],"figures":[],"tables":[]}],"workedExamples":[],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch23.sec03.feat01","type":"tip","title":"Tips for Success","text":"The Super-Kamiokande experiment is a clever use of proportional reasoning. Because it is not feasible to test for 10 31 years in order for a single proton to decay, scientists chose instead to manipulate the protontime ratio. If one proton decays in 10 31 years, then in one year 10 -31 protons will decay. With this in mind, if scientists wanted to test the proton decay theory in one year, they would need 10 31 protons. While this is also unfeasible, the use of a 50,000-ton tank of water helps to bring both the wait time and proton number to within reason.","images":[]}],"summaryPoints":["Attempts to show unification of the four forces are called Grand Unified Theories (GUTs) and have been partially successful, with connections proven between EM and weak forces in electroweak theory.","Unification of the strong force is expected at such high energies that it cannot be directly tested, but it may have observable consequences in the as-yet-unobserved decay of the proton. Although unification of forces is generally anticipated, much remains to be done to prove its validity."],"glossary":[{"term":"Big Bang","termVi":"Vụ Nổ Lớn (Big Bang)","definition":"a gigantic explosion that threw out matter a few billion years ago","definitionVi":"Sự kiện khởi đầu sự giãn nở của vũ trụ từ trạng thái cực nóng và cực đặc cách đây khoảng 13,8 tỷ năm.","memoryTipVi":"Vũ trụ vẫn đang tiếp tục giãn nở ngày nay."},{"term":"Electroweak Epoch","termVi":"Kỷ nguyên Điện yếu","definition":"the stage before 10 -11 back to 10 -34 seconds after the Big Bang","definitionVi":"Giai đoạn lực Mạnh đã tách riêng, còn lực Điện từ và lực Yếu vẫn thống nhất thành lực Điện yếu.","memoryTipVi":"10⁻³⁶ s đến 10⁻¹² s."},{"term":"electroweak theory","termVi":"Lý thuyết Điện yếu","definition":"theory showing connections between EM and weak forces","definitionVi":"Lý thuyết thống nhất thành công tương tác Điện từ và tương tác Yếu (giải Nobel 1979 cho Weinberg, Salam, Glashow).","memoryTipVi":"Đã được kiểm chứng thực nghiệm hoàn toàn!"},{"term":"Grand Unification Epoch","termVi":"Kỷ nguyên Đại thống nhất","definition":"the time period from 10 -43 to 10 -34 seconds after the Big Bang, when Grand Unification Theory, in which all forces except gravity are identical, governed the universe","definitionVi":"Giai đoạn vũ trụ sơ khai sau khi lực Hấp dẫn tách ra, còn 3 lực Mạnh, Yếu và Điện từ vẫn hợp nhất.","memoryTipVi":"10⁻⁴³ s đến 10⁻³⁶ s."},{"term":"Grand Unified Theory","termVi":"Lý thuyết Đại thống nhất (GUT)","definition":"theory that shows unification of the strong and electroweak forces","definitionVi":"Lý thuyết thống nhất 3 tương tác: Mạnh, Yếu và Điện từ ở năng lượng rất cao.","memoryTipVi":"Viết tắt: GUT."},{"term":"Inflationary Epoch","termVi":"Kỷ nguyên Lạm phát vũ trụ","definition":"the rapid expansion of the universe by an incredible factor of 10 -50 for the brief time from 10 -35 to about 10 -32 seconds","definitionVi":"Khoảnh khắc vũ trụ sơ khai giãn nở nhanh theo hàm mũ gấp hàng tỷ tỷ lần chỉ trong tích tắc.","memoryTipVi":"Giải thích tính đồng nhất của bức xạ nền vũ trụ."},{"term":"Planck Epoch","termVi":"Kỷ nguyên Planck (0 đến 10⁻⁴³ s)","definition":"the earliest era of the universe, before 10 –43 seconds after the Big Bang","definitionVi":"Khoảnh khắc đầu tiên ngay sau Big Bang khi cả 4 lực cơ bản được cho là hợp nhất thành một Siêu lực duy nhất.","memoryTipVi":"Trước 10⁻⁴³ giây."},{"term":"Quark Era","termVi":"Kỷ nguyên Quark","definition":"the time period from 10 –11 to 10 –6 seconds at which all four fundamental forces are separated and quarks begin to exit","definitionVi":"Giai đoạn vũ trụ còn quá nóng nên các hạt quark và gluon tồn tại tự do trước khi kết tụ thành proton và neutron.","memoryTipVi":"Quark–gluon plasma."},{"term":"superforce","termVi":"Siêu lực (Hợp nhất cả 4 lực cơ bản)","definition":"the unification of all four fundamental forces into one force","definitionVi":"Lực duy nhất hợp nhất Hấp dẫn, Mạnh, Yếu và Điện từ ở mức năng lượng cực đại của Kỷ nguyên Planck.","memoryTipVi":"Mục tiêu tối thượng của Vật lý lý thuyết."},{"term":"Theory of Everything","termVi":"Lý thuyết Vạn vật (TOE)","definition":"the theory that shows unification of all four fundamental forces","definitionVi":"Lý thuyết mơ ước thống nhất hoàn toàn Cơ học lượng tử (3 lực vi mô) với Thuyết tương đối rộng (Lực hấp dẫn).","memoryTipVi":"Thách thức lớn nhất chưa có lời giải trọn vẹn của Vật lý hiện đại!"}],"assessments":[{"uid":"hsphys.ch23.sec03.q001","sourceId":"fs-id1167067183611","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Is there one grand unified theory or multiple grand unifying theories?","images":[],"choices":[{"label":"a","text":"one grand unifying theory"},{"label":"b","text":"multiple grand unifying theories"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec03.q007","sourceId":"eip-id1166848776047","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"The existence of what particles were predicted as a consequence of the electroweak theory?","images":[],"choices":[{"label":"a","text":"fermions"},{"label":"b","text":"Higgs bosons"},{"label":"c","text":"leptons"},{"label":"d","text":"W + , W - , and Z 0 bosons"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec03.q009","sourceId":"fs-id1167067011348","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Why are scientists unable to model the conditions of the universe at time periods shortly after the Big Bang?","images":[],"choices":[{"label":"a","text":"The amount of energy necessary to replicate the Planck Epoch is too high."},{"label":"b","text":"The amount of energy necessary to replicate the Planck Epoch is too low."},{"label":"c","text":"The volume of setup necessary to replicate the Planck Epoch is too high."},{"label":"d","text":"The volume of setup necessary to replicate the Planck Epoch is too low."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec03.q011","sourceId":"eip-id1166851419922","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"What is the name for the theory of unification of all four fundamental forces?","images":[],"choices":[{"label":"a","text":"the theory of everything"},{"label":"b","text":"the theory of energy-to-mass conversion"},{"label":"c","text":"the theory of relativity"},{"label":"d","text":"the theory of the Big Bang"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec03.q014","sourceId":"fs-id1167063626667","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"If some unknown cause of the red shift, such as light becoming tired from traveling long distances through empty space, is discovered, what effect would there be on cosmology?","images":[],"choices":[{"label":"a","text":"The effect would be substantial, as the Big Bang is based on the idea that the red shift is evidence that galaxies are moving toward one another."},{"label":"b","text":"The effect would be substantial, as the Big Bang is based on the idea that the red shift is evidence that the galaxies are moving away from one another."},{"label":"c","text":"The effect would be substantial, as the Big Bang is based on the idea that the red shift is evidence that galaxies are neither moving away from nor moving toward one another."},{"label":"d","text":"The effect would be substantial, as the Big Bang is based on the idea that the red shift is evidence that galaxies are sometimes moving away from and sometimes moving toward one another."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec03.q017","sourceId":"fs-id1167066972995","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Which two forces were first combined, signifying the eventual desire for a Grand Unified Theory?","images":[],"choices":[{"label":"a","text":"electric force and magnetic forces"},{"label":"b","text":"electric force and weak nuclear force"},{"label":"c","text":"gravitational force and the weak nuclear force"},{"label":"d","text":"electroweak force and strong nuclear force"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec03.q018","sourceId":"fs-id1167067088247","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"After the Big Bang, what was the first force to separate from the others?","images":[],"choices":[{"label":"a","text":"electromagnetic force"},{"label":"b","text":"gravity"},{"label":"c","text":"strong nuclear force"},{"label":"d","text":"weak nuclear force"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec03.q019","sourceId":"fs-id1167067231162","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"What is the name of the device used by scientists to check for proton decay?","images":[],"choices":[{"label":"a","text":"the cyclotron"},{"label":"b","text":"the Large Hadron Collider"},{"label":"c","text":"the Super-Kamiokande"},{"label":"d","text":"the synchrotron"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec03.q020","sourceId":"eip-id1166846436367","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"How do Feynman diagrams suggest the Grand Unified Theory?","images":[],"choices":[{"label":"a","text":"The electromagnetic, weak, and strong nuclear forces all have similar Feynman diagrams."},{"label":"b","text":"The electromagnetic, weak, and gravitational forces all have similar Feynman diagrams."},{"label":"c","text":"The electromagnetic, weak, and strong forces all have different Feynman diagrams."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec03.q024","sourceId":"fs-id1167063798800","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"How does the search for the Grand Unified Theory help test the standard cosmological model?","images":[],"choices":[{"label":"a","text":"Scientists are increasing energy in the lab that models the energy in earlier, denser stages of the universe."},{"label":"b","text":"Scientists are increasing energy in the lab that models the energy in earlier, less dense stages of the universe."},{"label":"c","text":"Scientists are decreasing energy in the lab that models the energy in earlier, denser stages of the universe."},{"label":"d","text":"Scientists are decreasing energy in the lab that models the energy in earlier, less dense stages of the universe."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec03.q026","sourceId":"fs-id1167063483343","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"When accelerating elementary particles in a particle accelerator, they quickly achieve a speed approaching the speed of light. However, as time continues, the particles maintain this speed yet continue to increase their kinetic energy. How is this possible?","images":[],"choices":[{"label":"a","text":"The speed remains the same, but the masses of the particles increase."},{"label":"b","text":"The speed remains the same, but the masses of the particles decrease."},{"label":"c","text":"The speed remains the same, and the masses of the particles remain the same."},{"label":"d","text":"The speed and masses will remain the same, but temperature will increase."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec03.q027","sourceId":"fs-id1167063807983","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"If a Grand Unified Theory is proven and the four forces are unified, it will still be correct to say that the orbit of the Moon is determined by the gravitational force. Explain why.","images":[],"choices":[{"label":"a","text":"Gravity will not be a property of the unified force."},{"label":"b","text":"Gravity will be one property of the unified force."},{"label":"c","text":"Apart from gravity, no other force depends on the mass of the object."},{"label":"d","text":"Apart from gravity, no other force can make an object move in a fixed orbit."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch23.sec03.q028","sourceId":"fs-id1167063496225","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"As the universe expanded and temperatures dropped, the strong nuclear force separated from the electroweak force. Is it likely that under cooler conditions, the force of electricity will separate from the force of magnetism?","images":[],"choices":[{"label":"a","text":"No, the electric force relies on the magnetic force and vice versa."},{"label":"b","text":"Yes, the electric and magnetic forces can be separated from each other."}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":3,"keyEquationCount":0,"subsectionCount":3,"workedExampleCount":0,"snapLabCount":0,"glossaryCount":10,"assessmentCount":13}}],"summary":{"totalSections":4,"totalKeyEquations":0,"totalWorkedExamples":0,"totalSnapLabs":0,"totalGlossaryTerms":45,"totalAssessments":60,"referencedMediaCount":22},"qualityGate":{"passed":true,"checkedUids":75,"errors":[],"warnings":[]}};
